  "madayanti": { "av": "👸", "en": "Madayantī", "te": "మదయంతి", "d": "The faithful queen of King Saudāsa (Kalmāṣapāda). She gave her divine earrings to Uttaṅka.", "dt": "సౌదాస (కల్మాషపాద) మహారాజు పతివ్రత అయిన రాణి. తన దివ్య కుండలాలను ఉత్తంకునికి ఇచ్చింది." },
  "brihadashva": { "av": "👑", "en": "Bṛhadaśva", "te": "బృహదశ్వుడు", "d": "An Ikṣvāku king who, as he was leaving for the forest, was asked by Uttaṅka to rid the land of the demon Dhundhu.", "dt": "ఇక్ష్వాకు వంశపు రాజు. అడవికి బయలుదేరుతుండగా ధుంధుని బాధ తీర్చమని ఉత్తంకుడు ఆయనను కోరాడు." },
  "kuvalashva": { "av": "🏇", "en": "Kuvalāśva (Dhundhumāra)", "te": "కువలాశ్వుడు (ధుంధుమారుడు)", "d": "Son of Bṛhadaśva. Filled with Viṣṇu's power at Uttaṅka's prayer, he killed the demon Dhundhu and was named Dhundhumāra.", "dt": "బృహదశ్వుని కుమారుడు. ఉత్తంకుని ప్రార్థనతో విష్ణుతేజం నిండి ధుంధు రాక్షసుణ్ణి చంపి ‘ధుంధుమారుడు’ అనే పేరు పొందాడు." },
