window.SAGE_CHAPTERS = (window.SAGE_CHAPTERS || []).concat([
{
 id: "ut-1", sage: "uttanka", n: 1, order: 2401, date: "2026-10-25",
 title: "A Line of Patient Teachers", titleTe: "ఓర్పుగల గురువుల పరంపర",
 src: "Mahābhārata, Ādi Parva, Pauṣya Parva",
 who: ["uttanka", "dhaumya", "uddalaka", "upamanyu", "vedaguru"],
 pages: [
  [
   ["p", "Some sages are remembered for great hymns, some for great books. {uttanka|Uttaṅka} is remembered for one thing above all: what he was willing to go through for his teacher. He walked into a king's palace, crawled down into the world of the serpents, stood face to face with a man-eating king, and argued with Kṛṣṇa himself — all because of a promise made to a teacher, or a teacher's wife.", "కొందరు మునులు గొప్ప సూక్తాలతో, కొందరు గొప్ప గ్రంథాలతో గుర్తుండిపోతారు. {uttanka|ఉత్తంకుడు} మాత్రం అన్నిటికంటే ఒకే విషయంతో గుర్తుంటాడు — గురువు కోసం ఆయన ఎంత కష్టమైనా భరించడానికి సిద్ధపడ్డాడు. రాజభవనంలోకి నడిచి వెళ్ళాడు, పాతాళంలోని నాగలోకంలోకి దిగాడు, నరమాంసం తినే రాజుకు ఎదురుగా నిలబడ్డాడు, స్వయంగా శ్రీకృష్ణునితోనే వాదించాడు — ఇదంతా ఒక గురువుకో, గురుపత్నికో ఇచ్చిన మాట కోసమే."],
   ["p", "The Mahābhārata tells his life in three different places, and they do not fit together neatly. In the Ādi Parva, at the very beginning of the epic, Uttaṅka is the pupil of a teacher named Veda. In the Āśvamedhika Parva, near the end, he is the pupil of the great sage {gautama|Gautama}. And in the Vana Parva he is an old ascetic of the desert who sends a king to kill a demon. The two pupil-stories are so alike — earrings, a queen, serpents, a horse of fire — that they look like two tellings of one old tale.", "మహాభారతం ఆయన జీవితాన్ని మూడు చోట్ల చెబుతుంది; ఆ మూడూ పూర్తిగా ఒకదానితో ఒకటి కలవవు. ఇతిహాసం మొదట్లోనే ఉన్న ఆది పర్వంలో ఉత్తంకుడు ‘వేదుడు’ అనే గురువు శిష్యుడు. చివరి భాగంలోని ఆశ్వమేధిక పర్వంలో ఆయన మహాముని {gautama|గౌతముని} శిష్యుడు. అరణ్య పర్వంలోనేమో ఒక రాక్షసుణ్ణి చంపడానికి రాజును పంపే ఎడారి తపస్వి. రెండు శిష్యుని కథలూ — కుండలాలు, రాణి, నాగులు, అగ్ని గుర్రం — ఎంత దగ్గరగా ఉంటాయంటే, ఒకే ప్రాచీన కథకు రెండు కథనాలలా అనిపిస్తాయి."],
   ["p", "We will tell all three, one after another, and say each time which part of the epic is speaking. First comes the Ādi Parva — and to understand Uttaṅka's teacher, we must start with his teacher's teacher.", "మూడింటినీ ఒకదాని తరువాత ఒకటి చెప్పుకుందాం; ప్రతిసారీ ఇది ఇతిహాసంలోని ఏ భాగమో చెబుతూ వెళ్దాం. మొదట ఆది పర్వం. ఉత్తంకుని గురువును అర్థం చేసుకోవాలంటే, ఆ గురువు యొక్క గురువు దగ్గర మొదలుపెట్టాలి."]
  ],
  [
   ["h", "Āyoda Dhaumya and His Three Pupils", "ఆయోదధౌమ్యుడు — ఆయన ముగ్గురు శిష్యులు"],
   ["p", "There was a sage named {dhaumya|Āyoda Dhaumya}, who had three pupils. He tested each of them in a way that seems harsh to us — and each of them passed. The first, Āruṇi of Pāñcāla, was sent to stop a breach in the bank of a field. When nothing else held back the water, he lay down in the gap himself and stayed there. His teacher came looking, called him, and Āruṇi rose out of the channel. Because he had risen (ud-dalita) from the field-channel, the teacher named him {uddalaka|Uddālaka}.", "{dhaumya|ఆయోదధౌమ్యుడు} అనే మునికి ముగ్గురు శిష్యులు ఉండేవారు. ఆయన ఒక్కొక్కరినీ మనకు కఠినంగా అనిపించే విధంగా పరీక్షించాడు — ముగ్గురూ నెగ్గారు. మొదటివాడు పాంచాల దేశపు ఆరుణి. పొలం గట్టుకు పడిన గండిని ఆపమని గురువు పంపాడు. నీటిని ఆపడానికి ఏదీ పనిచేయకపోతే, ఆ గండిలో తానే అడ్డంగా పడుకుని ఉండిపోయాడు. గురువు వెతుక్కుంటూ వచ్చి పిలిస్తే, ఆ కాలువ నుండి లేచి వచ్చాడు. పొలం కాలువను చీల్చుకుని లేచినందున గురువు ఆయనకు {uddalaka|ఉద్దాలకుడు} అని పేరు పెట్టాడు."],
   ["p", "The second, {upamanyu|Upamanyu}, was set to herd the teacher's cows and forbidden, one by one, every way of feeding himself — begged food, milk, even the froth the calves left behind. At last, starving, he ate the leaves of the bitter arka plant, went blind, and fell into a dry well. His teacher had him pray to the twin physicians, the Aśvins, who gave him back his sight; and the teacher blessed him with all knowledge.", "రెండవవాడు {upamanyu|ఉపమన్యుడు}. గురువు ఆవులను మేపే పని ఇచ్చి, ఆయన ఆహారానికి ఉన్న ఒక్కొక్క దారినీ మూసేశాడు — భిక్షాన్నం వద్దు, పాలు వద్దు, దూడలు వదిలిన నురుగు కూడా వద్దు. చివరికి ఆకలికి తాళలేక జిల్లేడు ఆకులు తిని, కళ్ళు పోయి, ఒక పాడుబడిన బావిలో పడిపోయాడు. గురువు ఆయనతో అశ్వినీ దేవతలను ప్రార్థింపజేశాడు; వారు చూపు తిరిగి ఇచ్చారు; గురువు సకల విద్యలూ కలగాలని ఆశీర్వదించాడు."],
   ["p", "The third pupil was named {vedaguru|Veda}. His teacher told him simply, “Stay here and serve me.” So for a long time Veda carried loads like an ox yoked to a cart, suffered heat and cold, hunger and thirst, and never once complained. At the end of it his teacher was pleased, and Veda received all knowledge and every blessing.", "మూడవ శిష్యుని పేరు {vedaguru|వేదుడు}. గురువు ఆయనకు చెప్పింది ఒక్కటే — “ఇక్కడే ఉండి నాకు సేవ చెయ్యి.” అలా చాలా కాలం వేదుడు బండికి కట్టిన ఎద్దులా బరువులు మోశాడు; ఎండ, చలి, ఆకలి, దప్పిక భరించాడు; ఒక్కసారి కూడా ఫిర్యాదు చేయలేదు. చివరికి గురువు సంతోషించాడు; వేదునికి సకల విద్యలూ, సకల శుభాలూ కలిగాయి."]
  ],
  [
   ["h", "A Teacher Who Remembered His Own Pain", "తన బాధను మరువని గురువు"],
   ["p", "When Veda went home and became a householder, three pupils came to live with him in turn. And here the epic says something lovely: Veda never told his pupils to do this work or that, and never made them suffer, because he remembered how much he himself had suffered in his teacher's house. He knew what hardship was, and he did not pass it on.", "వేదుడు ఇంటికి వెళ్ళి గృహస్థుడయ్యాక, ఆయన దగ్గర కూడా ముగ్గురు శిష్యులు ఉండేవారు. ఇక్కడ ఇతిహాసం ఒక చక్కని మాట చెబుతుంది — వేదుడు తన శిష్యులకు ‘ఈ పని చెయ్యి, ఆ పని చెయ్యి’ అని ఎప్పుడూ ఆజ్ఞాపించలేదు, వారిని బాధపెట్టలేదు; ఎందుకంటే గురువు ఇంట్లో తాను పడిన కష్టం ఆయనకు బాగా గుర్తుంది. కష్టం అంటే ఏమిటో తెలిసినవాడు కాబట్టి, దాన్ని ఇంకొకరికి అందించలేదు."],
   ["p", "Kings honoured him. Two kṣatriyas, Janamejaya and {paushya|Pauṣya}, chose Veda as their family teacher and priest. One day Veda had to leave home to perform a sacrifice for one of them. He called his pupil {uttanka|Uttaṅka} and said, “Whatever is needed in this house while I am gone, see that it is done.” Then he left. That simple instruction was about to become Uttaṅka's first great test.", "రాజులు ఆయనను గౌరవించారు. జనమేజయుడు, {paushya|పౌష్యుడు} అనే ఇద్దరు క్షత్రియులు వేదుణ్ణి తమ ఆచార్యునిగా, పురోహితునిగా ఎంచుకున్నారు. ఒకసారి వారిలో ఒకరి కోసం యజ్ఞం చేయించడానికి వేదుడు ఇంటి నుండి బయలుదేరవలసి వచ్చింది. శిష్యుడు {uttanka|ఉత్తంకుణ్ణి} పిలిచి, “నేను లేనప్పుడు ఈ ఇంట్లో ఏది అవసరమైతే అది జరిగేలా చూడు” అని చెప్పి వెళ్ళాడు. ఆ చిన్న మాటే ఉత్తంకునికి మొదటి పెద్ద పరీక్ష కాబోతోంది."],
   ["dyk", "🐂", "The three pupils of Dhaumya are told at the very start of the Mahābhārata, before any king or war. The epic seems to say: before you hear about heroes, learn what it means to be a student.", "ధౌమ్యుని ముగ్గురు శిష్యుల కథలు మహాభారతం ప్రారంభంలోనే, ఏ రాజు, ఏ యుద్ధం కంటే ముందే వస్తాయి. ‘వీరుల గురించి వినడానికి ముందు, శిష్యుడంటే ఏమిటో నేర్చుకో’ అని ఇతిహాసం చెబుతున్నట్టుంటుంది."],
   ["src", "Mahābhārata, Ādi Parva, Pauṣya Parva — Āyoda Dhaumya's pupils Āruṇi (Uddālaka), Upamanyu and Veda; Veda's kindness to his own pupils; Janamejaya and Pauṣya choosing Veda as their teacher; Uttaṅka left in charge of the house.", "మహాభారతం, ఆది పర్వం, పౌష్య పర్వం — ఆయోదధౌమ్యుని శిష్యులు ఆరుణి (ఉద్దాలకుడు), ఉపమన్యుడు, వేదుడు; వేదుడు తన శిష్యుల పట్ల చూపిన దయ; జనమేజయుడు, పౌష్యుడు వేదుణ్ణి ఆచార్యునిగా ఎంచుకోవడం; ఇంటి బాధ్యత ఉత్తంకునికి అప్పగించడం."]
  ]
 ],
 remember: [
  ["The Mahābhārata tells {uttanka|Uttaṅka}'s life in three places: the Ādi, Āśvamedhika and Vana Parvas.", "మహాభారతం {uttanka|ఉత్తంకుని} జీవితాన్ని మూడు చోట్ల చెబుతుంది — ఆది, ఆశ్వమేధిక, అరణ్య పర్వాలలో."],
  ["{dhaumya|Āyoda Dhaumya}'s three pupils were Āruṇi, {upamanyu|Upamanyu} and {vedaguru|Veda}.", "{dhaumya|ఆయోదధౌమ్యుని} ముగ్గురు శిష్యులు — ఆరుణి, {upamanyu|ఉపమన్యుడు}, {vedaguru|వేదుడు}."],
  ["Veda, who had suffered as a pupil, never made his own pupils suffer.", "శిష్యునిగా కష్టాలు పడిన వేదుడు తన శిష్యులను ఎప్పుడూ కష్టపెట్టలేదు."]
 ],
 think: ["Veda chose not to pass on the hardship he had been through. Is there something hard you went through that you would never want someone younger to face?", "తాను పడిన కష్టాన్ని ఇంకొకరికి అందించకూడదని వేదుడు నిర్ణయించుకున్నాడు. మీరు పడిన ఏ కష్టం మీ కంటే చిన్నవారికి ఎప్పుడూ రాకూడదని అనుకుంటారు?"]
},
{
 id: "ut-2", sage: "uttanka", n: 2, order: 2402, date: "2026-10-25",
 title: "The Test in the Empty House", titleTe: "గురువు లేని ఇంట్లో పరీక్ష",
 src: "Mahābhārata, Ādi Parva, Pauṣya Parva",
 who: ["uttanka", "vedaguru"],
 pages: [
  [
   ["p", "{uttanka|Uttaṅka} lived in his teacher's house and did everything the house needed. Then a strange request came to him. The women of the household gathered and said: “Your teacher's wife has reached her season, the time when a child can be conceived, and your teacher is away. Do what is needed, so that her season does not pass in vain.” In plain words, they were asking the pupil to take the husband's place.", "{uttanka|ఉత్తంకుడు} గురువు ఇంట్లో ఉంటూ ఆ ఇంటికి కావలసిన పనులన్నీ చూసుకుంటున్నాడు. అంతలో ఆయనకు ఒక వింత కోరిక ఎదురైంది. ఇంట్లోని స్త్రీలు కూడి వచ్చి ఇలా అన్నారు: “నీ గురుపత్నికి ఋతుకాలం వచ్చింది — సంతానం కలిగే సమయం అది. నీ గురువు ఊళ్ళో లేడు. ఆ కాలం వృథా పోకుండా చేయవలసింది చెయ్యి.” సూటిగా చెప్పాలంటే, భర్త స్థానంలో శిష్యుణ్ణే ఉండమని వారు అడుగుతున్నారు."],
   ["p", "In those old days, people believed that letting a wife's season pass without a chance of children was a wrong in itself, and the women may have meant it as a duty, not a sin. But Uttaṅka did not hesitate. “I will not do a thing that should not be done just because women tell me to,” he said. “My teacher told me to see to what this house needs. He never told me to do what is improper.”", "ఆ ప్రాచీన కాలంలో, భార్య ఋతుకాలం సంతానం లేకుండా గడిచిపోవడమే ఒక దోషమని ప్రజలు నమ్మేవారు. ఆ స్త్రీలు దీన్ని పాపంగా కాక ఒక కర్తవ్యంగానే అనుకుని ఉండవచ్చు. కానీ ఉత్తంకుడు ఒక్క క్షణం కూడా తడబడలేదు. “స్త్రీలు చెప్పారని చేయకూడని పని నేను చేయను,” అన్నాడు. “ఈ ఇంటికి కావలసింది చూడమని మా గురువు చెప్పారు. చేయకూడనిది చేయమని ఆయన ఎప్పుడూ చెప్పలేదు.”"],
   ["dyk", "⚖️", "Notice how carefully Uttaṅka reads his teacher's words. “See to whatever the house needs” could be stretched to mean almost anything. Uttaṅka refuses to stretch it to cover a wrong.", "ఉత్తంకుడు గురువు మాటను ఎంత జాగ్రత్తగా అర్థం చేసుకున్నాడో గమనించండి. ‘ఇంటికి ఏది కావాలో అది చూడు’ అనే మాటను లాగి దాదాపు దేనికైనా అన్వయించవచ్చు. కానీ ఒక తప్పుకు దాన్ని సాగదీయడానికి ఉత్తంకుడు ఒప్పుకోలేదు."]
  ],
  [
   ["h", "The Teacher Comes Home", "గురువు తిరిగి వచ్చాడు"],
   ["p", "In time {vedaguru|Veda} returned from his journey and heard the whole story. He was deeply pleased. “My child, Uttaṅka,” he said, “what good thing can I do for you? You have served me as dharma asks. Our love for each other has grown. Go now, with my leave — and all your wishes will come true.”", "కొంత కాలానికి {vedaguru|వేదుడు} ప్రయాణం ముగించుకుని తిరిగి వచ్చాడు; జరిగినదంతా విన్నాడు. ఆయన మనసు ఎంతో సంతోషించింది. “నాయనా ఉత్తంకా, నీకు నేనేం మేలు చేయగలను? ధర్మం కోరినట్లే నువ్వు నాకు సేవ చేశావు. మన ఇద్దరి మధ్య ప్రేమ పెరిగింది. నా అనుమతితో ఇక వెళ్ళు — నీ కోరికలన్నీ నెరవేరుతాయి” అన్నాడు."],
   ["p", "But a pupil does not leave his teacher's house empty-handed. There was a custom: at the end of one's studies, one gives the teacher a gift, the guru-dakṣiṇā. “What shall I bring you?” Uttaṅka asked. “The wise say that when one teaches without dharma, or learns without dharma, one of the two comes to harm. Tell me what you would like.”", "కానీ శిష్యుడు గురువు ఇంటి నుండి వట్టి చేతులతో వెళ్ళడు. విద్య పూర్తయ్యాక గురువుకు కానుక ఇవ్వడం ఆచారం — అదే గురుదక్షిణ. “మీకు ఏం తీసుకురమ్మంటారు?” అని ఉత్తంకుడు అడిగాడు. “ధర్మం లేకుండా బోధించినా, ధర్మం లేకుండా నేర్చుకున్నా ఆ ఇద్దరిలో ఒకరికి కీడు జరుగుతుందని పెద్దలు చెబుతారు. మీకు ఏం కావాలో చెప్పండి.”"],
   ["p", "Veda said gently, “Stay a little longer, then.” After some time Uttaṅka asked again. This time his teacher said, “Go in and ask your teacher's wife. Whatever she asks for, bring that.”", "వేదుడు మెల్లగా, “అయితే ఇంకొంత కాలం ఉండు” అన్నాడు. కొంత కాలం తరువాత ఉత్తంకుడు మళ్ళీ అడిగాడు. ఈసారి గురువు, “లోపలికి వెళ్ళి మీ గురుపత్నిని అడుగు. ఆమె ఏది కోరితే అది తీసుకురా” అన్నాడు."]
  ],
  [
   ["h", "Four Days", "నాలుగు రోజులు"],
   ["p", "Uttaṅka went to his teacher's wife. “My teacher has given me leave to go home,” he said. “I want to bring you something, so that I do not leave owing a debt. Tell me what you want.”", "ఉత్తంకుడు గురుపత్ని దగ్గరకు వెళ్ళాడు. “ఇంటికి వెళ్ళడానికి గురువుగారు అనుమతి ఇచ్చారు. ఋణం తీర్చుకోకుండా వెళ్ళకూడదని మీకు ఏదైనా తేవాలనుకుంటున్నాను. ఏం కావాలో చెప్పండి” అన్నాడు."],
   ["p", "She answered at once: “Go to King {paushya|Pauṣya}, and ask for the pair of earrings his queen wears. Bring them here. Four days from now I am keeping a sacred vow, and I want to serve food to the brāhmaṇas wearing those earrings. If you bring them in time, good will come to you. If not, what good can you expect?”", "ఆమె వెంటనే చెప్పింది: “{paushya|పౌష్య} మహారాజు దగ్గరకు వెళ్ళు. ఆయన రాణి ధరించే కుండలాల జంటను అడిగి ఇక్కడికి తీసుకురా. ఈ రోజు నుండి నాలుగో రోజున నేను ఒక పుణ్య వ్రతం చేస్తున్నాను. ఆ కుండలాలు పెట్టుకుని బ్రాహ్మణులకు వడ్డించాలని నా కోరిక. సమయానికి తెస్తే నీకు మేలు జరుగుతుంది. తేకపోతే నీకు మేలు ఎక్కడిది?”"],
   ["p", "So the quiet pupil who had refused to cross a line in the empty house set out on the road, with four days to fetch a queen's earrings from a king's palace. He could not know that the road would lead him under the earth.", "ఖాళీ ఇంట్లో గీత దాటడానికి ఒప్పుకోని ఆ నెమ్మదైన శిష్యుడు, ఒక రాజభవనం నుండి రాణి కుండలాలు తేవడానికి నాలుగు రోజుల గడువుతో దారి పట్టాడు. ఆ దారి తనను భూమి కిందికి తీసుకెళ్తుందని ఆయనకు అప్పుడు తెలియదు."],
   ["src", "Mahābhārata, Ādi Parva, Pauṣya Parva — the women's request and Uttaṅka's refusal; Veda's blessing; the guru-dakṣiṇā; the teacher's wife asking for Pauṣya's queen's earrings within four days.", "మహాభారతం, ఆది పర్వం, పౌష్య పర్వం — స్త్రీల కోరిక, ఉత్తంకుని తిరస్కారం; వేదుని ఆశీర్వాదం; గురుదక్షిణ; నాలుగు రోజుల్లో పౌష్యుని రాణి కుండలాలు తెమ్మని గురుపత్ని కోరడం."]
  ]
 ],
 remember: [
  ["Left in charge of the house, {uttanka|Uttaṅka} refused to take his teacher's place with his teacher's wife.", "ఇంటి బాధ్యత ఉన్నప్పుడు, గురువు స్థానంలో గురుపత్నితో ఉండమన్న కోరికను {uttanka|ఉత్తంకుడు} తిరస్కరించాడు."],
  ["“My teacher never told me to do what is improper.”", "“చేయకూడనిది చేయమని మా గురువు ఎప్పుడూ చెప్పలేదు.”"],
  ["For her guru-dakṣiṇā the teacher's wife asked for King {paushya|Pauṣya}'s queen's earrings, within four days.", "గురుదక్షిణగా నాలుగు రోజుల్లో {paushya|పౌష్యుని} రాణి కుండలాలు తెమ్మని గురుపత్ని కోరింది."]
 ],
 think: ["Uttaṅka was told to do “whatever the house needs”, yet he knew where that instruction ended. How do you tell when someone's words are being stretched to cover something wrong?", "‘ఇంటికి ఏది కావాలో అది చెయ్యి’ అని చెప్పినా, ఆ మాట ఎక్కడ ఆగుతుందో ఉత్తంకునికి తెలుసు. ఎవరి మాటనైనా ఒక తప్పును కప్పడానికి సాగదీస్తున్నారని మీరు ఎలా గుర్తిస్తారు?"]
},
{
 id: "ut-3", sage: "uttanka", n: 3, order: 2403, date: "2026-10-25",
 title: "The Bull on the Road and the Queen No One Could See", titleTe: "దారిలో ఎద్దు — ఎవరికీ కనిపించని రాణి",
 src: "Mahābhārata, Ādi Parva, Pauṣya Parva",
 who: ["uttanka", "paushya", "takshaka"],
 pages: [
  [
   ["p", "On the road {uttanka|Uttaṅka} saw an enormous bull, and riding on it a man of enormous size. The man called out: “Uttaṅka! Eat the dung of this bull.” Uttaṅka stood still. He did not want to do it. The man spoke again: “Eat it, Uttaṅka. Do not hesitate. Your teacher ate it too, long ago.”", "దారిలో {uttanka|ఉత్తంకునికి} ఒక మహా పెద్ద ఎద్దు, దాని మీద ఎక్కిన ఒక మహాకాయుడు కనిపించారు. ఆ మనిషి పిలిచాడు: “ఉత్తంకా! ఈ ఎద్దు పేడను తిను.” ఉత్తంకుడు అలాగే నిలబడిపోయాడు; తినాలని లేదు. ఆ మనిషి మళ్ళీ అన్నాడు: “తిను ఉత్తంకా, సంకోచించకు. ఎప్పుడో మీ గురువు కూడా తిన్నాడు.”"],
   ["p", "At the words “your teacher ate it too”, Uttaṅka gave in. He said, “So be it,” and ate the bull's dung and drank its urine. Then, in a hurry to be on his way, he rinsed his mouth while still standing, and walked on. That small hurried rinse — not done in the proper way, seated and facing east — would matter very soon.", "‘మీ గురువు కూడా తిన్నాడు’ అనే మాట వినగానే ఉత్తంకుడు ఒప్పుకున్నాడు. “సరే” అని ఎద్దు పేడను తిని, మూత్రాన్ని కూడా తాగాడు. తరువాత తొందరగా దారి పట్టాలని నిలబడే నోరు పుక్కిలించుకుని ముందుకు నడిచాడు. సరిగా కూర్చుని, తూర్పు ముఖంగా చేయవలసిన ఆచమనం అలా తొందరలో చేసినది — అది త్వరలోనే ఒక సమస్య తెచ్చిపెట్టింది."],
   ["dyk", "🐄", "To an Indian reader, cow-dung and cow-urine are not simply dirt — they are used even today in rites of purification. Still, being told to eat them on a road by a stranger was a hard test of trust. The meaning of this strange meeting is explained only at the end of the story.", "భారతీయులకు ఆవు పేడ, గోమూత్రం కేవలం మురికి కాదు — ఈనాటికీ శుద్ధి కర్మల్లో వాడతారు. అయినా, దారిలో ఒక అపరిచితుడు వాటిని తినమంటే అది నమ్మకానికి గట్టి పరీక్షే. ఈ వింత కలయిక అర్థం కథ చివర్లోనే తెలుస్తుంది."]
  ],
  [
   ["h", "At King Pauṣya's Palace", "పౌష్య మహారాజు భవనంలో"],
   ["p", "Uttaṅka reached King {paushya|Pauṣya}, who was seated in his hall. He blessed the king and said, “I have come to you as a seeker. I ask for your queen's earrings, as the gift I owe my teacher.” Pauṣya bowed. “Go into the inner rooms,” he said, “and ask the queen herself.”", "ఉత్తంకుడు సభలో కూర్చుని ఉన్న {paushya|పౌష్య} మహారాజు దగ్గరకు చేరాడు. రాజును ఆశీర్వదించి, “యాచకునిగా మీ దగ్గరకు వచ్చాను. నా గురుదక్షిణ కోసం మీ రాణి కుండలాలను అడుగుతున్నాను” అన్నాడు. పౌష్యుడు నమస్కరించి, “అంతఃపురానికి వెళ్ళి రాణినే అడగండి” అన్నాడు."],
   ["p", "Uttaṅka went into the queen's apartments — and could not find her anywhere. He came back to the king, upset. “It is not right for you to deceive me,” he said. “Your queen is not in the inner rooms. I could not see her.”", "ఉత్తంకుడు అంతఃపురంలోకి వెళ్ళాడు — కానీ ఎక్కడా రాణి కనిపించలేదు. బాధపడి రాజు దగ్గరకు తిరిగి వచ్చి, “నన్ను మోసం చేయడం మీకు తగదు. అంతఃపురంలో మీ రాణి లేదు; నాకు కనిపించలేదు” అన్నాడు."],
   ["p", "Pauṣya thought for a moment and said, “Sir, think back. You must be in a state of impurity. My queen is a faithful wife, devoted to her husband; one who is impure cannot see her.” Uttaṅka remembered at once. “Yes — I was in a hurry, and I rinsed my mouth standing as I walked.” “That is it,” said the king. “Rinsing while standing or moving is not rinsing at all.”", "పౌష్యుడు ఒక్క క్షణం ఆలోచించి, “స్వామీ, ఒకసారి గుర్తు చేసుకోండి. మీరు అశుచిగా ఉండి ఉండాలి. నా రాణి పతివ్రత; అశుచిగా ఉన్నవారికి ఆమె కనిపించదు” అన్నాడు. ఉత్తంకునికి వెంటనే గుర్తొచ్చింది. “అవును — తొందరలో నడుస్తూ, నిలబడే ఆచమనం చేశాను.” “అదే కారణం,” అన్నాడు రాజు. “నిలబడి గానీ, నడుస్తూ గానీ చేసినది ఆచమనమే కాదు.”"]
  ],
  [
   ["h", "The Earrings, and a Warning", "కుండలాలు — ఒక హెచ్చరిక"],
   ["p", "Uttaṅka sat down facing east, washed his hands, feet and face properly, sipped water silently, touched the openings of his body with water as the rite prescribes, and went back into the inner rooms. This time he saw the queen at once. She rose to greet him, honoured him, and asked what he wanted. When he told her, she was glad — “You are a worthy guest” — and took off her earrings and gave them to him.", "ఉత్తంకుడు తూర్పు ముఖంగా కూర్చుని, చేతులు, కాళ్ళు, ముఖం శుభ్రంగా కడుక్కుని, మౌనంగా ఆచమనం చేసి, విధి ప్రకారం శరీర ఇంద్రియాలను నీటితో తాకి, మళ్ళీ అంతఃపురంలోకి వెళ్ళాడు. ఈసారి రాణి వెంటనే కనిపించింది. ఆమె లేచి ఎదురొచ్చి గౌరవించి, ఏం కావాలని అడిగింది. ఆయన చెప్పగానే సంతోషించి — “మీరు తగిన అతిథి” అంటూ — తన కుండలాలు తీసి ఆయనకు ఇచ్చింది."],
   ["p", "Then she added a warning: “The serpent king {takshaka|Takṣaka} has wanted these earrings for a long time. Guard them carefully as you go.” Uttaṅka answered, “Do not worry, my lady. Takṣaka cannot overpower me.” He bowed to her and left the inner rooms — sure of himself, and not yet knowing how cunning a serpent could be.", "తరువాత ఒక హెచ్చరిక చేసింది: “నాగరాజు {takshaka|తక్షకుడు} చాలా కాలంగా ఈ కుండలాల కోసం ఆశపడుతున్నాడు. దారిలో జాగ్రత్తగా కాపాడుకోండి.” ఉత్తంకుడు, “అమ్మా, దిగులు పడకండి. తక్షకుడు నన్ను జయించలేడు” అని బదులిచ్చాడు. ఆమెకు నమస్కరించి అంతఃపురం నుండి బయటికి వచ్చాడు — తనపై గట్టి నమ్మకంతో; ఒక సర్పం ఎంత కుటిలంగా ఉండగలదో ఇంకా తెలియకుండా."],
   ["src", "Mahābhārata, Ādi Parva, Pauṣya Parva — the man on the great bull; Uttaṅka's hurried rinsing; the queen unseen by one who was impure; his purification and the gift of the earrings; the warning about Takṣaka.", "మహాభారతం, ఆది పర్వం, పౌష్య పర్వం — మహా ఎద్దుపై మనిషి; ఉత్తంకుని తొందర ఆచమనం; అశుచికి కనిపించని రాణి; శుద్ధి చేసుకుని కుండలాలు పొందడం; తక్షకుని గురించి హెచ్చరిక."]
  ]
 ],
 remember: [
  ["A giant man on a giant bull told {uttanka|Uttaṅka} to eat its dung — “your teacher ate it too.”", "మహా ఎద్దుపై మహాకాయుడు దాని పేడను తినమని {uttanka|ఉత్తంకునికి} చెప్పాడు — “మీ గురువు కూడా తిన్నాడు.”"],
  ["Because he had rinsed his mouth standing, he could not see {paushya|Pauṣya}'s faithful queen.", "నిలబడి ఆచమనం చేసినందుకు {paushya|పౌష్యుని} పతివ్రత అయిన రాణి ఆయనకు కనిపించలేదు."],
  ["The queen gave him the earrings, warning that {takshaka|Takṣaka} wanted them.", "తక్షకుడు వాటి కోసం ఆశపడుతున్నాడని హెచ్చరిస్తూ రాణి కుండలాలు ఇచ్చింది."]
 ],
 think: ["Uttaṅka could not see the queen until he slowed down and did a simple thing properly. When has rushing made you miss something right in front of you?", "నెమ్మదించి ఒక చిన్న పనిని సరిగా చేసేవరకు ఉత్తంకునికి రాణి కనిపించలేదు. తొందర వల్ల మీ కళ్ళ ముందే ఉన్నదాన్ని మీరు ఎప్పుడైనా చూడలేకపోయారా?"]
},
{
 id: "ut-4", sage: "uttanka", n: 4, order: 2404, date: "2026-10-25",
 title: "Two Curses at King Pauṣya's Table", titleTe: "పౌష్యుని భోజనశాలలో రెండు శాపాలు",
 src: "Mahābhārata, Ādi Parva, Pauṣya Parva",
 who: ["uttanka", "paushya"],
 pages: [
  [
   ["p", "As {uttanka|Uttaṅka} came out, King {paushya|Pauṣya} said to him, “Sir, a worthy guest is not found every day, and you are one of great virtue. I wish to perform a śrāddha, an offering of food. Please stay a little while and eat.” Uttaṅka agreed: “Then let it be quick. Bring whatever food is ready.”", "ఉత్తంకుడు బయటికి రాగానే {paushya|పౌష్య} మహారాజు, “స్వామీ, తగిన అతిథి ప్రతి రోజూ దొరకడు; మీరు గొప్ప గుణవంతులు. నేను శ్రాద్ధం — అన్నదానం — చేయాలనుకుంటున్నాను. కాసేపు ఉండి భోజనం చేయండి” అన్నాడు. {uttanka|ఉత్తంకుడు} ఒప్పుకున్నాడు: “అయితే త్వరగా కానివ్వండి. సిద్ధంగా ఉన్న అన్నమే తీసుకురండి.”"],
   ["p", "The food was brought. Uttaṅka looked at it: it was cold, and there was a hair in it. To a brāhmaṇa this was impure food, unfit to be offered to a guest. Uttaṅka's anger flared. “You have given me impure food,” he said. “Therefore you will become blind.”", "అన్నం వచ్చింది. ఉత్తంకుడు చూశాడు — అది చల్లారిపోయి ఉంది; అందులో ఒక వెంట్రుక ఉంది. బ్రాహ్మణునికి అది అశుచి అన్నం; అతిథికి వడ్డించదగినది కాదు. ఉత్తంకునికి కోపం ముంచుకొచ్చింది. “నాకు అశుచి అన్నం పెట్టావు. అందుకే నువ్వు గుడ్డివాడివి అవుతావు” అన్నాడు."],
   ["p", "Pauṣya was a king, and a proud one. “And since you find fault with pure food,” he shot back, “you will have no children!”", "పౌష్యుడు రాజు; అభిమానం గలవాడు. “పవిత్రమైన అన్నానికి దోషం పెడుతున్నావు కాబట్టి, నీకు సంతానం ఉండదు!” అని వెంటనే ప్రతిశాపం ఇచ్చాడు."]
  ],
  [
   ["h", "Who Was Right?", "ఎవరిది న్యాయం?"],
   ["p", "“It is not right,” said Uttaṅka, “for you to curse me back after giving me impure food. Look at it yourself.” Pauṣya looked. The food was cold, and there was a hair in it — it had been prepared by a woman whose hair was loose. The king's anger turned to shame. “Sir, this was done without my knowing. The food is cold and has a hair in it. Forgive me. Let me not become blind.”", "“నాకు అశుచి అన్నం పెట్టి, మళ్ళీ నన్నే శపించడం నీకు తగదు,” అన్నాడు ఉత్తంకుడు. “నువ్వే చూడు.” పౌష్యుడు చూశాడు. అన్నం చల్లగా ఉంది, అందులో వెంట్రుక ఉంది — జుట్టు విరబోసుకున్న ఒక స్త్రీ దాన్ని వండింది. రాజు కోపం సిగ్గుగా మారింది. “స్వామీ, ఇది నాకు తెలియకుండా జరిగింది. అన్నం చల్లగా ఉంది, వెంట్రుక ఉంది. నన్ను క్షమించండి. నేను గుడ్డివాణ్ణి కాకుండా చూడండి.”"],
   ["p", "Uttaṅka said, “What I have said cannot become false. You will become blind — but before long you will see again. Now you, too, take back your curse on me.”", "ఉత్తంకుడు అన్నాడు: “నేను అన్న మాట అబద్ధం కాదు. నువ్వు గుడ్డివాడివి అవుతావు — కానీ కొద్ది కాలంలోనే మళ్ళీ చూపు వస్తుంది. ఇప్పుడు నువ్వు కూడా నాపై పెట్టిన శాపాన్ని వెనక్కి తీసుకో.”"]
  ],
  [
   ["h", "Butter and the Razor", "వెన్న — కత్తి అంచు"],
   ["p", "“I cannot take it back,” Pauṣya said. “My anger has not yet cooled. Do you not know this saying? A brāhmaṇa's heart is soft like fresh butter, but his words are sharp like a razor. With a kṣatriya it is the other way round: his words are soft like butter, but his heart is sharp like a razor. Being a kṣatriya, with my heart still sharp, I am not able to undo my curse. Go.”", "“దాన్ని వెనక్కి తీసుకోలేను,” అన్నాడు పౌష్యుడు. “నా కోపం ఇంకా చల్లారలేదు. ఈ మాట నీకు తెలియదా? బ్రాహ్మణుని హృదయం అప్పుడే తీసిన వెన్నలా మెత్తగా ఉంటుంది, కానీ అతని మాట కత్తి అంచులా పదునుగా ఉంటుంది. క్షత్రియునిది అందుకు వ్యతిరేకం — మాట వెన్నలా మెత్తన, హృదయం కత్తి అంచులా పదును. క్షత్రియుణ్ణి, హృదయం ఇంకా పదునుగానే ఉంది కాబట్టి నా శాపాన్ని తిప్పలేను. వెళ్ళండి.”"],
   ["p", "Uttaṅka answered calmly: “You yourself saw that the food was impure and asked my pardon. You cursed me for blaming pure food — but the food was not pure. So your curse will not touch me.” And with the earrings safely in hand, he set out again on the road.", "ఉత్తంకుడు ప్రశాంతంగా బదులిచ్చాడు: “అన్నం అశుచి అని నువ్వే చూసి క్షమించమన్నావు. పవిత్రమైన అన్నాన్ని నిందించినందుకు నన్ను శపించావు — కానీ ఆ అన్నం పవిత్రమైనది కాదు. కాబట్టి నీ శాపం నాకు అంటదు.” కుండలాలను భద్రంగా పట్టుకుని మళ్ళీ దారి పట్టాడు."],
   ["dyk", "🧈", "The butter-and-razor saying is one of the most quoted lines of the Pauṣya Parva. It is the king's excuse for not cooling down — but it also hints at a truth both men shared: each was quick to curse, and slow to forgive.", "వెన్న–కత్తి అంచు సామెత పౌష్య పర్వంలో చాలా తరచుగా ఉదహరించబడే మాట. కోపం తగ్గించుకోలేకపోవడానికి అది రాజు చెప్పిన సాకు — కానీ ఆ ఇద్దరిలోనూ ఉన్న ఒక నిజాన్ని కూడా సూచిస్తుంది: ఇద్దరూ శపించడంలో తొందర, క్షమించడంలో ఆలస్యం."],
   ["src", "Mahābhārata, Ādi Parva, Pauṣya Parva — the śrāddha meal, the cold food with a hair in it, Uttaṅka's curse of blindness and Pauṣya's curse of childlessness, the saying about butter and the razor, and why Pauṣya's curse failed.", "మహాభారతం, ఆది పర్వం, పౌష్య పర్వం — శ్రాద్ధ భోజనం, వెంట్రుక ఉన్న చల్లని అన్నం, ఉత్తంకుని అంధత్వ శాపం, పౌష్యుని సంతాన రాహిత్య శాపం, వెన్న–కత్తి అంచు సామెత, పౌష్యుని శాపం ఎందుకు పనిచేయలేదో."]
  ]
 ],
 remember: [
  ["Served cold food with a hair in it, {uttanka|Uttaṅka} cursed {paushya|Pauṣya} with blindness — for a short while.", "వెంట్రుక ఉన్న చల్లని అన్నం పెట్టినందుకు {uttanka|ఉత్తంకుడు} {paushya|పౌష్యుణ్ణి} కొంత కాలం గుడ్డితనం కలగాలని శపించాడు."],
  ["Pauṣya cursed him back with childlessness, but the curse failed because the food really was impure.", "పౌష్యుడు సంతానం ఉండదని ప్రతిశాపం ఇచ్చాడు; అన్నం నిజంగా అశుచి కాబట్టి ఆ శాపం పనిచేయలేదు."],
  ["A brāhmaṇa's heart is like butter and his words like a razor; a kṣatriya's, the other way round.", "బ్రాహ్మణుని హృదయం వెన్న, మాట కత్తి అంచు; క్షత్రియునిది అందుకు వ్యతిరేకం."]
 ],
 think: ["Both Uttaṅka and Pauṣya cursed first and looked closely later. What would have changed if either had simply asked a question before speaking?", "ఉత్తంకుడు, పౌష్యుడు — ఇద్దరూ ముందు శపించి, తరువాత పరిశీలించారు. మాట్లాడే ముందు ఎవరైనా ఒక్క ప్రశ్న అడిగి ఉంటే ఏం మారేది?"]
},
{
 id: "ut-5", sage: "uttanka", n: 5, order: 2405, date: "2026-10-25",
 title: "Down to the World of the Serpents", titleTe: "నాగలోకానికి దిగడం",
 src: "Mahābhārata, Ādi Parva, Pauṣya Parva",
 who: ["uttanka", "takshaka", "indra"],
 pages: [
  [
   ["p", "On the road {uttanka|Uttaṅka} noticed a naked beggar coming along behind him, now seen, now unseen. After a while Uttaṅka put the earrings down on the ground and went to the water to wash. In that moment the beggar ran up, snatched the earrings, and fled.", "దారిలో వెనకాలే ఒక దిగంబర భిక్షువు వస్తున్నట్టు {uttanka|ఉత్తంకుడు} గమనించాడు — ఒకసారి కనిపిస్తూ, ఒకసారి మాయమవుతూ. కొంతసేపటికి ఉత్తంకుడు కుండలాలను నేల మీద పెట్టి స్నానానికి, ఆచమనానికి నీటి దగ్గరకు వెళ్ళాడు. ఆ క్షణంలోనే ఆ భిక్షువు పరిగెత్తుకొచ్చి కుండలాలను లాక్కుని పారిపోయాడు."],
   ["p", "Uttaṅka finished his washing, purified himself, bowed to the gods and his teachers, and ran after the thief as fast as he could. He caught him. But the moment he seized him, the beggar threw off his disguise. He was {takshaka|Takṣaka}, the serpent king. Slipping free, Takṣaka dived into a great hole in the earth and went down to his own home, the world of the nāgas.", "ఉత్తంకుడు స్నానం ముగించి, శుచి అయి, దేవతలకు, గురువులకు నమస్కరించి, శక్తి కొద్దీ ఆ దొంగ వెనక పరిగెత్తాడు. పట్టుకున్నాడు కూడా. కానీ పట్టుకున్న క్షణంలోనే ఆ భిక్షువు తన వేషం వదిలేశాడు — అతడు నాగరాజు {takshaka|తక్షకుడు}. చేతి నుండి జారిపోయి, భూమిలోని ఒక పెద్ద బిలంలోకి దూకి, తన ఇల్లయిన నాగలోకానికి దిగిపోయాడు."],
   ["p", "Uttaṅka remembered the queen's warning. He took a stick and began to dig at the hole. He dug and dug, but a man with a stick cannot dig down to the underworld. Then {indra|Indra}, watching from heaven, saw the young man's struggle. He sent his thunderbolt, the vajra, and told it: “Go and help this brāhmaṇa.” The vajra entered Uttaṅka's stick, and with the next stroke the earth split open.", "రాణి హెచ్చరిక ఉత్తంకునికి గుర్తొచ్చింది. ఒక కర్ర తీసుకుని ఆ బిలాన్ని తవ్వడం మొదలుపెట్టాడు. తవ్వాడు, తవ్వాడు — కానీ కర్రతో పాతాళం దాకా ఎవరు తవ్వగలరు? అప్పుడు స్వర్గం నుండి చూస్తున్న {indra|ఇంద్రుడు} ఆ యువకుని పోరాటం చూశాడు. తన వజ్రాయుధాన్ని పంపి, “వెళ్ళి ఈ బ్రాహ్మణునికి సహాయం చెయ్యి” అన్నాడు. వజ్రం ఉత్తంకుని కర్రలో ప్రవేశించింది; తరువాతి దెబ్బకే భూమి చీలిపోయింది."]
  ],
  [
   ["h", "Wonders in the Underworld", "పాతాళంలో వింతలు"],
   ["p", "Uttaṅka went down the opening and found himself in the land of the serpents — endless, full of palaces, towers, gateways and places of play. He stood and praised the nāgas with verses: the great serpents of Airāvata's clan, who shine in battle like the sun; Takṣaka, who lives in Kurukṣetra and the Khāṇḍava forest; and others. But for all his praise, the earrings did not come back.", "ఉత్తంకుడు ఆ దారిలో కిందికి దిగాడు — అంతులేని నాగలోకం కనిపించింది; భవనాలు, గోపురాలు, ద్వారాలు, క్రీడా స్థలాలతో నిండి ఉంది. అక్కడ నిలబడి నాగులను శ్లోకాలతో స్తుతించాడు — యుద్ధంలో సూర్యునిలా ప్రకాశించే ఐరావత వంశపు మహానాగులను, కురుక్షేత్రంలోనూ ఖాండవ వనంలోనూ నివసించే తక్షకుణ్ణి, ఇంకా ఎందరినో. ఎంత స్తుతించినా కుండలాలు మాత్రం తిరిగి రాలేదు."],
   ["p", "Then he saw strange sights. Two women sat at a loom, weaving a cloth with threads of black and white. A wheel with twelve spokes was being turned by six boys. And there was a man, very handsome, and beside him a fine horse. Uttaṅka did not know who they were, but he sensed they were great powers, and he praised them too, with mantras about the turning wheel, the weaving of the threads, and the lord of the three worlds.", "అప్పుడు ఆయనకు వింత దృశ్యాలు కనిపించాయి. ఇద్దరు స్త్రీలు మగ్గం మీద కూర్చుని నలుపు, తెలుపు దారాలతో వస్త్రం నేస్తున్నారు. పన్నెండు ఆకులున్న ఒక చక్రాన్ని ఆరుగురు బాలురు తిప్పుతున్నారు. ఒక అందమైన పురుషుడు, అతని పక్కన ఒక చక్కని గుర్రం ఉన్నారు. వీరెవరో ఉత్తంకునికి తెలియదు; కానీ మహాశక్తులని గ్రహించి — తిరిగే చక్రం గురించి, నేసే దారాల గురించి, ముల్లోకాల ప్రభువు గురించి మంత్రాలతో — వారిని కూడా స్తుతించాడు."]
  ],
  [
   ["h", "Blow into the Horse", "గుర్రంలోకి ఊదు"],
   ["p", "The man said, “I am pleased with your praise. What can I do for you?” Uttaṅka said, “Let the serpents come under my power.” The man answered: “Blow into the back of this horse.” Uttaṅka blew — and from every opening of the horse's body burst flames and thick smoke. The smoke rolled through the whole world of the serpents.", "ఆ పురుషుడు, “నీ స్తుతికి సంతోషించాను. నీకేం చేయగలను?” అన్నాడు. “నాగులు నా వశం కావాలి” అన్నాడు ఉత్తంకుడు. ఆ పురుషుడు చెప్పాడు: “ఈ గుర్రం వెనుక భాగంలోకి ఊదు.” ఉత్తంకుడు ఊదాడు — గుర్రం శరీరంలోని ప్రతి ద్వారం నుండి మంటలు, దట్టమైన పొగ బయటికి వచ్చాయి. ఆ పొగ నాగలోకమంతటా కమ్ముకుంది."],
   ["p", "Choking, terrified of the fire, {takshaka|Takṣaka} came rushing out of his house with the earrings. “Sir, take back your earrings!” he cried. Uttaṅka took them — and then his heart sank. “Today is my teacher's wife's sacred day, and I am far down under the earth. How can I reach her in time?” The man said, “Ride this horse, Uttaṅka. In a moment it will carry you to your teacher's house.”", "ఊపిరాడక, మంటలకు భయపడి {takshaka|తక్షకుడు} కుండలాలు పట్టుకుని తన ఇంటి నుండి పరుగెత్తుకొచ్చాడు. “స్వామీ, మీ కుండలాలు తీసుకోండి!” అని అరిచాడు. ఉత్తంకుడు తీసుకున్నాడు — వెంటనే ఆయన గుండె జారిపోయింది. “ఈ రోజే గురుపత్ని వ్రతం. నేనేమో భూమి అడుగున ఎంతో దూరంలో ఉన్నాను. సమయానికి ఎలా చేరగలను?” ఆ పురుషుడు అన్నాడు: “ఉత్తంకా, ఈ గుర్రం ఎక్కు. క్షణంలో నిన్ను గురువు ఇంటికి చేరుస్తుంది.”"],
   ["p", "The horse flew. At the teacher's house, the teacher's wife had bathed and was sitting combing her hair, thinking, “Uttaṅka has not come,” and was just making up her mind to curse him — when he walked in, bowed, and gave her the earrings. Her anger melted. “You have come at the right time, at the right place,” she said. “Welcome, my child. You did no wrong, so I did not curse you. May good fortune come to you; may you gain your wishes.”", "గుర్రం ఎగిరింది. గురువు ఇంట్లో గురుపత్ని స్నానం చేసి, కూర్చుని తల దువ్వుకుంటూ ‘ఉత్తంకుడు రాలేదు’ అనుకుంటూ, అతణ్ణి శపించాలని నిర్ణయించుకుంటోంది — అంతలో ఆయన లోపలికి వచ్చి, నమస్కరించి, కుండలాలు ఆమెకు అందించాడు. ఆమె కోపం కరిగిపోయింది. “సరైన సమయానికి, సరైన చోటికి వచ్చావు నాయనా. స్వాగతం. నువ్వు తప్పు చేయలేదు కాబట్టే నిన్ను శపించలేదు. నీకు శుభం కలుగుగాక; నీ కోరికలు నెరవేరుగాక” అంది."],
   ["src", "Mahābhārata, Ādi Parva, Pauṣya Parva — the naked beggar who was Takṣaka; Indra's vajra entering Uttaṅka's stick; his praises of the nāgas; the two weavers, the twelve-spoked wheel, the man and the horse; the smoke that forced Takṣaka out; the ride home and the teacher's wife's blessing.", "మహాభారతం, ఆది పర్వం, పౌష్య పర్వం — తక్షకుడే అయిన దిగంబర భిక్షువు; ఉత్తంకుని కర్రలో ప్రవేశించిన ఇంద్రుని వజ్రం; నాగ స్తుతి; ఇద్దరు నేతగత్తెలు, పన్నెండు ఆకుల చక్రం, పురుషుడు, గుర్రం; తక్షకుణ్ణి బయటికి రప్పించిన పొగ; ఇంటికి ప్రయాణం, గురుపత్ని ఆశీర్వాదం."]
  ]
 ],
 remember: [
  ["{takshaka|Takṣaka}, disguised as a naked beggar, stole the earrings and fled into the earth.", "దిగంబర భిక్షువు వేషంలో {takshaka|తక్షకుడు} కుండలాలు దొంగిలించి భూమిలోకి పారిపోయాడు."],
  ["{indra|Indra}'s thunderbolt entered {uttanka|Uttaṅka}'s stick and opened the way to the serpent world.", "{indra|ఇంద్రుని} వజ్రం {uttanka|ఉత్తంకుని} కర్రలో ప్రవేశించి నాగలోకానికి దారి తెరిచింది."],
  ["Smoke and fire from a wondrous horse forced Takṣaka to give the earrings back.", "అద్భుత గుర్రం నుండి వచ్చిన పొగ, మంటల వల్ల తక్షకుడు కుండలాలు తిరిగి ఇచ్చాడు."]
 ],
 think: ["Uttaṅka's praise did not move the serpents, but his praise of the strangers at the loom brought him help. Why do you think the story puts it that way?", "ఉత్తంకుని స్తుతి నాగులను కదిలించలేదు; కానీ మగ్గం దగ్గరి అపరిచితులను స్తుతిస్తే సహాయం దొరికింది. కథ ఇలా ఎందుకు చెబుతుందని మీరు అనుకుంటున్నారు?"]
},
{
 id: "ut-6", sage: "uttanka", n: 6, order: 2406, date: "2026-10-25",
 title: "What the Wonders Meant — and the Fire He Lit in Hastināpura", titleTe: "ఆ వింతల అర్థం — హస్తినాపురంలో రగిలించిన అగ్ని",
 src: "Mahābhārata, Ādi Parva, Pauṣya and Āstīka Parvas",
 who: ["uttanka", "vedaguru", "parjanya", "agni", "airavata", "indra", "janamejaya", "parikshit", "takshaka", "astika"],
 pages: [
  [
   ["p", "{uttanka|Uttaṅka} went to his teacher and bowed. “Welcome, my child,” said {vedaguru|Veda}. “Why did you take so long?” Uttaṅka told him everything — Takṣaka's theft, the vajra, the serpent world. “And there I saw two women weaving with black and white threads. What was that? And a wheel of twelve spokes turned by six boys — what was that? And who was the man, and what was the great horse? And on the road I met a bull with a man riding it, who spoke to me kindly and told me to eat its dung — and by eating it I came to the serpent world. Who was he?”", "{uttanka|ఉత్తంకుడు} గురువు దగ్గరకు వెళ్ళి నమస్కరించాడు. “స్వాగతం నాయనా. ఇంత ఆలస్యం ఎందుకైంది?” అని {vedaguru|వేదుడు} అడిగాడు. ఉత్తంకుడు జరిగినదంతా చెప్పాడు — తక్షకుని దొంగతనం, వజ్రం, నాగలోకం. “అక్కడ ఇద్దరు స్త్రీలు నలుపు తెలుపు దారాలతో నేస్తూ కనిపించారు — వారెవరు? ఆరుగురు బాలురు తిప్పుతున్న పన్నెండు ఆకుల చక్రం — అదేమిటి? ఆ పురుషుడెవరు, ఆ మహా గుర్రం ఏమిటి? దారిలో ఎద్దుపై ఒక మనిషి కనిపించి ప్రేమగా మాట్లాడి దాని పేడ తినమన్నాడు — అది తిన్నందుకే నాగలోకానికి చేరగలిగాను. అతనెవరు?”"],
   ["h", "The Teacher Explains", "గురువు వివరణ"],
   ["p", "Veda answered: “The two women are Dhātā and Vidhātā, who ordain all things. The black and white threads are night and day. The wheel with twelve spokes is the year, and the six boys who turn it are the six seasons. The man you saw is {parjanya|Parjanya}, lord of the rain-clouds, and the horse is {agni|Agni}, the fire. The bull you met on the road is {airavata|Airāvata}, king of the elephants, and the man riding it is {indra|Indra}. The dung you ate was amṛta, the nectar of immortality — that is why you did not die in the land of the serpents.”", "వేదుడు చెప్పాడు: “ఆ ఇద్దరు స్త్రీలు సమస్తాన్నీ నిర్ణయించే ధాత, విధాత. నలుపు తెలుపు దారాలు రాత్రి, పగలు. పన్నెండు ఆకుల చక్రం సంవత్సరం; దాన్ని తిప్పే ఆరుగురు బాలురు ఆరు ఋతువులు. నువ్వు చూసిన పురుషుడు మేఘాల ప్రభువు {parjanya|పర్జన్యుడు}; ఆ గుర్రం {agni|అగ్నిదేవుడు}. దారిలో కనిపించిన ఎద్దు గజరాజు {airavata|ఐరావతం}; దాని మీద ఉన్నది {indra|ఇంద్రుడు}. నువ్వు తిన్న పేడ అమృతం — అందుకే నాగలోకంలో నువ్వు చనిపోలేదు.”"],
   ["p", "“Indra is my friend,” Veda went on. “It was by his kindness that you got the earrings and came back safely. Go now, my child. I give you leave. You will find good fortune.”", "“ఇంద్రుడు నా మిత్రుడు,” అని వేదుడు కొనసాగించాడు. “ఆయన దయ వల్లనే నువ్వు కుండలాలు పొంది క్షేమంగా తిరిగి వచ్చావు. ఇక వెళ్ళు నాయనా. నీకు అనుమతి ఇస్తున్నాను. నీకు శుభం కలుగుతుంది.”"]
  ],
  [
   ["h", "Uttaṅka Goes to Hastināpura", "హస్తినాపురానికి ఉత్తంకుడు"],
   ["p", "So the earrings were delivered and the debt was paid. But Uttaṅka did not forget {takshaka|Takṣaka}. His anger at the serpent who had robbed him and nearly ruined his teacher's vow burned on. He went to Hastināpura, to the young King {janamejaya|Janamejaya}, who had just come home victorious from Takṣaśilā.", "కుండలాలు చేరాయి, ఋణం తీరింది. కానీ ఉత్తంకుడు {takshaka|తక్షకుణ్ణి} మరువలేదు. తనను దోచుకుని, గురుపత్ని వ్రతాన్ని దాదాపు భంగం చేసిన ఆ సర్పం మీద కోపం రగులుతూనే ఉంది. ఆయన హస్తినాపురానికి, తక్షశిల నుండి విజయంతో తిరిగి వచ్చిన యువరాజు {janamejaya|జనమేజయ} మహారాజు దగ్గరకు వెళ్ళాడు."],
   ["p", "Standing before the king, Uttaṅka spoke sharply: “Best of kings, there is a task that needs doing, and you are busy with something else, like a child. Takṣaka killed your father, the great {parikshit|Parīkṣit}. Not only that — a healer named Kāśyapa was hurrying to save him, and Takṣaka turned him back. Avenge your father. Hold a snake sacrifice and burn that wicked serpent in its blazing fire. You will pay your father's debt, and you will do me a great kindness too — for that same wicked one stood in the way of my teacher's work.”", "రాజు ఎదుట నిలబడి ఉత్తంకుడు తీవ్రంగా మాట్లాడాడు: “రాజశ్రేష్ఠా, చేయవలసిన పని ఒకటి ఉంది; మీరేమో పిల్లవాడిలా వేరే పనుల్లో ఉన్నారు. మీ తండ్రి మహానుభావుడు {parikshit|పరీక్షిత్తును} చంపింది తక్షకుడే. అంతేకాదు — ఆయనను కాపాడడానికి కాశ్యపుడనే వైద్యుడు త్వరపడి వస్తుంటే, తక్షకుడు అతణ్ణి వెనక్కి పంపేశాడు. మీ తండ్రికి జరిగిన అన్యాయానికి ప్రతీకారం తీర్చుకోండి. సర్పయాగం చేసి ఆ దుష్ట సర్పాన్ని మండే అగ్నిలో కాల్చండి. మీ తండ్రి ఋణం తీరుతుంది; నాకూ గొప్ప మేలు చేసినవారవుతారు — ఎందుకంటే ఆ దుష్టుడే నా గురువు పనికి అడ్డు వచ్చాడు.”"],
   ["sglink", "Kāśyapa the Healer and Takṣaka", "వైద్యుడు కాశ్యపుడు, తక్షకుడు", "ks-8"]
  ],
  [
   ["h", "The Snake Sacrifice", "సర్పయాగం"],
   ["p", "Janamejaya had been a child when his father died, and did not know the whole story. Grief and anger rose in him. He questioned his ministers, heard how his father had died, and swore to do what Uttaṅka asked. So began the great snake sacrifice. Priests in black robes, their eyes red with smoke, poured offerings into the fire and called the serpents by name, and serpents of every kind came falling helplessly into the flames.", "తండ్రి చనిపోయినప్పుడు జనమేజయుడు చిన్నపిల్లవాడు; పూర్తి కథ ఆయనకు తెలియదు. దుఃఖం, కోపం ఆయనలో పొంగాయి. మంత్రులను అడిగి, తండ్రి ఎలా చనిపోయాడో విని, ఉత్తంకుడు కోరినట్లే చేస్తానని ప్రతిజ్ఞ చేశాడు. అలా మహా సర్పయాగం మొదలైంది. నల్లని వస్త్రాలు ధరించి, పొగకు కళ్ళు ఎర్రబడిన ఋత్విక్కులు అగ్నిలో ఆహుతులు వేస్తూ సర్పాల పేర్లు పిలుస్తుంటే, అన్ని రకాల సర్పాలు నిస్సహాయంగా మంటల్లో వచ్చి పడ్డాయి."],
   ["p", "Takṣaka fled to Indra for shelter. But the mantras were so strong that they began to drag Indra himself towards the fire along with him, and Indra let go. In the end it was the boy-sage {astika|Āstīka}, whose mother was a serpent-maiden, who won a boon from Janamejaya and asked that the sacrifice stop. Takṣaka was saved. And at that same sacrifice the Mahābhārata was told for the first time. So Uttaṅka's anger at one serpent became the setting for the whole great epic.", "తక్షకుడు ఆశ్రయం కోసం ఇంద్రుని దగ్గరకు పారిపోయాడు. కానీ మంత్రాలు ఎంత బలంగా ఉన్నాయంటే, అతనితో పాటు ఇంద్రుణ్ణి కూడా అగ్ని వైపు లాగడం మొదలుపెట్టాయి; ఇంద్రుడు తక్షకుణ్ణి వదిలేశాడు. చివరికి నాగకన్యకు పుట్టిన బాల ముని {astika|ఆస్తీకుడు} జనమేజయుని నుండి వరం పొంది, యాగం ఆపమని కోరాడు. తక్షకుడు బతికిపోయాడు. అదే యాగంలో మహాభారతం మొదటిసారి చెప్పబడింది. అలా ఒక సర్పంపై ఉత్తంకునికి వచ్చిన కోపమే ఈ మహేతిహాసమంతటికీ వేదిక అయింది."],
   ["sglink", "The Fifth Veda — and its first telling", "పంచమ వేదం — దాని మొదటి కథనం", "vy-8"],
   ["dyk", "🔥", "The Mahābhārata never praises Uttaṅka's anger, and it does not hide it either. It simply shows how one man's grudge, joined to a king's grief, lit a fire that nearly destroyed a whole race of beings — and how a child's request put it out.", "మహాభారతం ఉత్తంకుని కోపాన్ని పొగడదు, దాచదు కూడా. ఒక మనిషి పగ ఒక రాజు దుఃఖంతో కలిసి, ఒక జాతినే దాదాపు నాశనం చేసే అగ్నిని ఎలా రగిలించిందో — ఒక బాలుని కోరిక దాన్ని ఎలా ఆర్పిందో — కేవలం చూపిస్తుంది."],
   ["src", "Mahābhārata, Ādi Parva, end of the Pauṣya Parva — Veda's explanation of the wonders and Uttaṅka's visit to Janamejaya. The story of Parīkṣit's death, the snake sacrifice and Āstīka's boon: Ādi Parva, Āstīka Parva.", "మహాభారతం, ఆది పర్వం, పౌష్య పర్వం చివర — వింతల గురించి వేదుని వివరణ, జనమేజయుని దగ్గరకు ఉత్తంకుని రాక. పరీక్షిత్తు మరణం, సర్పయాగం, ఆస్తీకుని వరం: ఆది పర్వం, ఆస్తీక పర్వం."]
  ]
 ],
 remember: [
  ["The weavers were night and day, the wheel was the year, the horse was {agni|Agni} and the bull's dung was amṛta.", "నేతగత్తెలు రాత్రి పగలు, చక్రం సంవత్సరం, గుర్రం {agni|అగ్ని}, ఎద్దు పేడ అమృతం."],
  ["{uttanka|Uttaṅka} urged {janamejaya|Janamejaya} to avenge {parikshit|Parīkṣit} with a snake sacrifice.", "{parikshit|పరీక్షిత్తు} మరణానికి ప్రతీకారంగా సర్పయాగం చేయమని {uttanka|ఉత్తంకుడు} {janamejaya|జనమేజయుణ్ణి} పురికొల్పాడు."],
  ["{astika|Āstīka} stopped the sacrifice — and there the Mahābhārata was first told.", "{astika|ఆస్తీకుడు} ఆ యాగాన్ని ఆపాడు — అక్కడే మహాభారతం మొదటిసారి చెప్పబడింది."]
 ],
 think: ["Uttaṅka's grudge against one serpent led to the burning of thousands. When does a just anger turn into something bigger than the wrong that caused it?", "ఒక్క సర్పంపై ఉత్తంకుని పగ వేలాది సర్పాల దహనానికి దారితీసింది. న్యాయమైన కోపం ఎప్పుడు దానికి కారణమైన తప్పు కంటే పెద్దదిగా మారుతుంది?"]
},
{
 id: "ut-7", sage: "uttanka", n: 7, order: 2407, date: "2026-10-25",
 title: "Grown Old in Gautama's House", titleTe: "గౌతముని ఇంట్లో వృద్ధుడైన శిష్యుడు",
 src: "Mahābhārata, Āśvamedhika Parva",
 who: ["uttanka", "gautama", "ahalya", "janamejaya"],
 pages: [
  [
   ["p", "Now we turn to the second telling, near the end of the Mahābhārata, in the Āśvamedhika Parva. There, after hearing how {uttanka|Uttaṅka} once dared to threaten Kṛṣṇa with a curse, King {janamejaya|Janamejaya} asks: “What great tapas did this Uttaṅka have, that he could even think of cursing Kṛṣṇa?” And the storyteller Vaiśampāyana tells him of Uttaṅka's youth — with a different teacher.", "ఇప్పుడు రెండవ కథనానికి వెళ్దాం — మహాభారతం చివర్లోని ఆశ్వమేధిక పర్వం. అక్కడ {uttanka|ఉత్తంకుడు} ఒకప్పుడు శ్రీకృష్ణుణ్ణే శపిస్తానని బెదిరించాడని విన్న {janamejaya|జనమేజయ} మహారాజు ఇలా అడుగుతాడు: “కృష్ణుణ్ణి శపించాలని ఆలోచించగలిగేంత గొప్ప తపస్సు ఈ ఉత్తంకునికి ఎక్కడిది?” అప్పుడు కథకుడు వైశంపాయనుడు ఉత్తంకుని యవ్వనం గురించి చెబుతాడు — వేరొక గురువుతో."],
   ["p", "In this telling Uttaṅka is the pupil of the great sage {gautama|Gautama}, husband of {ahalya|Ahalyā}. Of all Gautama's pupils, none served him like Uttaṅka — with such devotion, such purity, such untiring care. Gautama loved him for it. Thousands of other pupils finished their studies and were sent home with their teacher's blessing. But Gautama could not bring himself to send Uttaṅka away.", "ఈ కథనంలో ఉత్తంకుడు అహల్యాదేవి భర్త అయిన మహాముని {gautama|గౌతముని} శిష్యుడు. గౌతముని శిష్యులందరిలో ఉత్తంకునిలా సేవ చేసినవారు లేరు — అంత భక్తి, అంత శుచి, అలుపెరుగని అంత శ్రద్ధ. అందుకే గౌతమునికి ఆయనంటే ఎంతో ప్రేమ. వేలాది శిష్యులు విద్య ముగించుకుని గురువు ఆశీర్వాదంతో ఇళ్ళకు వెళ్ళారు. కానీ ఉత్తంకుణ్ణి పంపడానికి మాత్రం గౌతమునికి మనసు రాలేదు."],
   ["sglink", "Gautama and Ahalyā", "గౌతముడు, అహల్య", "gt-2"]
  ],
  [
   ["h", "The White Hair on the Firewood", "కట్టెల మీద తెల్ల వెంట్రుక"],
   ["p", "Years went by — so many that Uttaṅka grew old without even noticing. One day he came back from the forest carrying a huge load of firewood. He was worn out, and he threw the load down on the ground. A lock of his hair had caught in the wood, and as the bundle fell it pulled the hair with it. Uttaṅka looked down — and saw that his hair was white. He was an old man. He had spent his whole life in his teacher's house. Hungry, tired and heartbroken, he began to weep.", "సంవత్సరాలు గడిచిపోయాయి — ఎన్నంటే, తాను ముసలివాడైపోయానని ఉత్తంకుడు గమనించనే లేదు. ఒక రోజు అడవి నుండి పెద్ద కట్టెల మోపు మోసుకొచ్చాడు. బాగా అలసిపోయి ఆ మోపును నేల మీద పడేశాడు. ఆయన జుట్టు ఒక పాయ కట్టెలకు చిక్కుకుని, మోపుతో పాటే జారి పడింది. ఉత్తంకుడు కిందికి చూశాడు — ఆ జుట్టు తెల్లగా ఉంది. తాను ముసలివాడు. జీవితమంతా గురువు ఇంట్లోనే గడిచిపోయింది. ఆకలితో, అలసటతో, మనసు విరిగి ఏడవడం మొదలుపెట్టాడు."],
   ["p", "Gautama's daughter, at her father's bidding, came and caught Uttaṅka's falling tears in her hands. But the tears of that great ascetic were so hot with his tapas that they burned her hands, and she had to let them fall to the earth. Even the earth could not hold them.", "తండ్రి ఆజ్ఞతో గౌతముని కుమార్తె వచ్చి, రాలుతున్న ఉత్తంకుని కన్నీటిని తన దోసిళ్ళలో పట్టుకుంది. కానీ ఆ మహాతపస్వి కన్నీళ్ళు తపస్సు వేడితో ఎంతగా మండుతున్నాయంటే, అవి ఆమె చేతులను కాల్చేశాయి; ఆమె వాటిని నేలమీద వదిలేయవలసి వచ్చింది. భూమి కూడా వాటిని భరించలేకపోయింది."],
   ["p", "Gautama asked gently, “Why is your heart so troubled today, my child? Tell me the truth.” Uttaṅka said, “My mind was always on you. I did not notice old age coming. I have lived here a hundred years, it seems, and you never gave me leave. Hundreds and thousands of pupils younger than I have gone home, and I am still here.”", "గౌతముడు మృదువుగా అడిగాడు: “నాయనా, ఈ రోజు నీ మనసు ఎందుకింత బాధగా ఉంది? నిజం చెప్పు.” ఉత్తంకుడు అన్నాడు: “నా మనసంతా ఎప్పుడూ మీ మీదే ఉంది. ముసలితనం వస్తున్నది గమనించలేదు. ఇక్కడ నూరేళ్ళు గడిపినట్టుంది; మీరు నాకు ఎప్పుడూ వెళ్ళమని అనుమతి ఇవ్వలేదు. నాకంటే చిన్నవారు వందలు, వేలు ఇళ్ళకు వెళ్ళిపోయారు; నేను మాత్రం ఇక్కడే ఉన్నాను.”"]
  ],
  [
   ["h", "Young Again, and a Bride", "మళ్ళీ యవ్వనం — వధువు"],
   ["p", "Gautama was moved. “It was my love and my pleasure in your service that made me forget the time,” he said. “Now, if you wish to go, go with my leave, today.” And by the power of his tapas Gautama made Uttaṅka young again. Then he said, “I will give you my daughter as your wife. No other woman could bear your fiery energy.” So Uttaṅka married his teacher's daughter — the same girl whose hands his tears had burned.", "గౌతముని మనసు కరిగింది. “నీ సేవపై నాకున్న ప్రేమ, సంతోషమే కాలాన్ని మరపించింది,” అన్నాడు. “ఇప్పుడు నువ్వు వెళ్ళాలనుకుంటే ఈ రోజే నా అనుమతితో వెళ్ళు.” తన తపశ్శక్తితో గౌతముడు ఉత్తంకుణ్ణి మళ్ళీ యువకుణ్ణి చేశాడు. తరువాత, “నా కుమార్తెను నీకు భార్యగా ఇస్తాను. నీ తేజస్సును ఇంకే స్త్రీ భరించలేదు” అన్నాడు. అలా ఉత్తంకుడు గురువు కుమార్తెను పెళ్ళి చేసుకున్నాడు — తన కన్నీళ్ళు ఎవరి చేతులను కాల్చాయో ఆ అమ్మాయినే."],
   ["p", "Before leaving, Uttaṅka asked, as every good pupil must, “What shall I bring you as my teacher's gift?” Gautama said, “You have pleased me — that is gift enough.” But Uttaṅka insisted, and Gautama said, “Then ask your teacher's mother — ask {ahalya|Ahalyā}.” Ahalyā said: “Bring me the divine earrings that King Saudāsa's queen wears.”", "బయలుదేరే ముందు, మంచి శిష్యుడు అడగవలసినట్లే ఉత్తంకుడు అడిగాడు: “గురుదక్షిణగా మీకు ఏం తీసుకురావాలి?” “నువ్వు నన్ను సంతోషపెట్టావు — అదే చాలు” అన్నాడు గౌతముడు. కానీ ఉత్తంకుడు పట్టుబట్టాడు. అప్పుడు గౌతముడు, “అయితే మీ గురుమాత {ahalya|అహల్యను} అడుగు” అన్నాడు. అహల్య చెప్పింది: “సౌదాస మహారాజు రాణి ధరించే దివ్య కుండలాలు తీసుకురా.”"],
   ["dyk", "😮", "Gautama gave in, but he knew what Ahalyā was asking. Saudāsa at that time was no ordinary king: under a curse he had become a man-eater who roamed the forest. Uttaṅka was being sent to ask a gift from someone who might simply eat him.", "గౌతముడు ఒప్పుకున్నాడు, కానీ అహల్య అడిగిన దాని అర్థం ఆయనకు తెలుసు. ఆ కాలంలో సౌదాసుడు సామాన్య రాజు కాదు — శాపం వల్ల అడవిలో తిరిగే నరమాంస భక్షకుడయ్యాడు. తనను తినేయగల వాని దగ్గరకే కానుక అడగడానికి ఉత్తంకుణ్ణి పంపుతున్నారు."],
   ["src", "Mahābhārata, Āśvamedhika Parva, the Uttaṅka episode told by Vaiśampāyana to Janamejaya — Uttaṅka's service to Gautama, his old age, the burning tears, his youth restored, his marriage to Gautama's daughter, and Ahalyā's request for Saudāsa's queen's earrings.", "మహాభారతం, ఆశ్వమేధిక పర్వం, వైశంపాయనుడు జనమేజయునికి చెప్పిన ఉత్తంకోపాఖ్యానం — గౌతమునికి ఉత్తంకుని సేవ, ముసలితనం, మండే కన్నీళ్ళు, మళ్ళీ వచ్చిన యవ్వనం, గౌతముని కుమార్తెతో వివాహం, సౌదాసుని రాణి కుండలాల కోసం అహల్య కోరిక."]
  ]
 ],
 remember: [
  ["In the Āśvamedhika Parva, {uttanka|Uttaṅka} is the pupil of {gautama|Gautama}, who loved him too much to send him away.", "ఆశ్వమేధిక పర్వంలో {uttanka|ఉత్తంకుడు} {gautama|గౌతముని} శిష్యుడు; ప్రేమ వల్ల గౌతముడు ఆయనను పంపలేకపోయాడు."],
  ["Seeing his own white hair, he wept; his tears burned the hands of Gautama's daughter.", "తన తెల్ల జుట్టు చూసి ఏడ్చాడు; ఆ కన్నీళ్ళు గౌతముని కుమార్తె చేతులను కాల్చాయి."],
  ["Made young again, he married her, and {ahalya|Ahalyā} asked for Saudāsa's queen's earrings.", "మళ్ళీ యువకుడై ఆమెను పెళ్ళాడాడు; {ahalya|అహల్య} సౌదాసుని రాణి కుండలాలు కోరింది."]
 ],
 think: ["Uttaṅka was so absorbed in his work that a whole lifetime slipped past. Is that a blessing, or a warning — or both?", "పనిలో ఎంతగా లీనమయ్యాడంటే జీవితమంతా ఉత్తంకునికి తెలియకుండానే గడిచిపోయింది. ఇది వరమా, హెచ్చరికా — లేక రెండూనా?"]
},
{
 id: "ut-8", sage: "uttanka", n: 8, order: 2408, date: "2026-10-25",
 title: "The Man-Eating King's Queen", titleTe: "నరమాంస భక్షకుడైన రాజు రాణి",
 src: "Mahābhārata, Āśvamedhika Parva",
 who: ["uttanka", "kalmashapada", "madayanti", "indra", "agni", "ahalya", "gautama"],
 pages: [
  [
   ["p", "{uttanka|Uttaṅka} went into the forest to find King Saudāsa, also called {kalmashapada|Kalmāṣapāda}. He found a terrible figure: huge, with a long beard, smeared with blood, wandering in the lonely woods. The king, possessed by the curse that had made him a man-eater, looked at the young brāhmaṇa and said, “You have come at the very hour when I look for my food. You are my meal.”", "{uttanka|ఉత్తంకుడు} {kalmashapada|కల్మాషపాదుడు} అని కూడా పిలవబడే సౌదాస మహారాజును వెతుక్కుంటూ అడవిలోకి వెళ్ళాడు. ఆయనకు ఒక భయంకర రూపం కనిపించింది — మహాకాయం, పొడవాటి గడ్డం, ఒంటి నిండా రక్తం, నిర్జనమైన అడవిలో తిరుగుతూ. నరమాంస భక్షకునిగా మార్చిన శాపం ఆవహించి ఉన్న ఆ రాజు ఈ యువ బ్రాహ్మణుణ్ణి చూసి, “నేను ఆహారం కోసం వెతికే సమయానికే వచ్చావు. నువ్వే నా ఆహారం” అన్నాడు."],
   ["p", "Uttaṅka did not run. “King, know that I have come here on my teacher's errand,” he said. “Let me first finish my teacher's work. When I have done it, I give you my word — I will come back to you, and you may do with me as you please.” Saudāsa asked what the errand was. “I have come to ask for your queen's earrings.” Strange as it sounds, the man-eater agreed. “Go and ask her,” he said, and told Uttaṅka where to find the queen.", "ఉత్తంకుడు పారిపోలేదు. “రాజా, నా గురువు పని మీద ఇక్కడికి వచ్చానని తెలుసుకో,” అన్నాడు. “ముందు నా గురువు పని పూర్తి చేయనివ్వు. అది అయ్యాక నీ దగ్గరకు తిరిగి వస్తానని మాట ఇస్తున్నాను — అప్పుడు నీ ఇష్టం వచ్చినట్లు చేయి.” ఏం పని అని సౌదాసుడు అడిగాడు. “మీ రాణి కుండలాలు అడగడానికి వచ్చాను.” వింతగా అనిపించినా, ఆ నరభక్షకుడు ఒప్పుకున్నాడు. “వెళ్ళి ఆమెనే అడుగు” అని రాణి ఎక్కడ ఉంటుందో చెప్పాడు."],
   ["sglink", "How Kalmāṣapāda became a man-eater", "కల్మాషపాదుడు నరభక్షకుడైన విధం", "va-7"]
  ],
  [
   ["h", "Madayantī", "మదయంతి"],
   ["p", "The queen, {madayanti|Madayantī}, was a faithful wife who had stayed true to her husband through his curse. When Uttaṅka asked for the earrings, she said, “How can I know my husband really sent you? Bring me a sign from him.” Uttaṅka went back to the forest, and Saudāsa gave him a message for her — words she would know could come only from him. When she heard them, she took off her divine earrings and gave them to Uttaṅka.", "రాణి {madayanti|మదయంతి} పతివ్రత; భర్త శాపంలో ఉన్నా ఆయనకే నిబద్ధురాలై ఉంది. ఉత్తంకుడు కుండలాలు అడగగానే, “నా భర్తే నిన్ను పంపాడని నాకెలా తెలుస్తుంది? ఆయన దగ్గరి నుండి ఏదైనా గుర్తు తీసుకురా” అంది. ఉత్తంకుడు మళ్ళీ అడవికి వెళ్ళాడు; సౌదాసుడు ఆమెకు ఒక సందేశం ఇచ్చాడు — తన దగ్గరి నుండి తప్ప ఇంకెవరి నుండీ రాదని ఆమెకు తెలిసే మాటలు. అవి వినగానే ఆమె తన దివ్య కుండలాలు తీసి ఉత్తంకునికి ఇచ్చింది."],
   ["p", "She warned him how precious and how dangerous they were: gods, yakṣas, serpents and others longed for them and watched for any moment of carelessness — if they were set down on the ground, the serpents would carry them off. Then Uttaṅka did something remarkable. He went back to the man-eater, as he had promised. Saudāsa, moved that a brāhmaṇa would walk back to his own death to keep his word, let him go — and advised him not to come that way again.", "అవి ఎంత విలువైనవో, ఎంత ప్రమాదకరమైనవో ఆమె హెచ్చరించింది: దేవతలు, యక్షులు, నాగులు మొదలైనవారు వాటి కోసం ఆశపడి, ఏ చిన్న అజాగ్రత్త కోసమైనా కాచుకుని ఉంటారు — నేల మీద పెడితే నాగులు ఎత్తుకుపోతారు. అప్పుడు ఉత్తంకుడు ఒక అద్భుతమైన పని చేశాడు. మాట ఇచ్చినట్లే మళ్ళీ ఆ నరభక్షకుని దగ్గరకు వెళ్ళాడు. మాట నిలబెట్టుకోవడానికి తన మరణం వైపే తిరిగి నడిచి వచ్చిన బ్రాహ్మణుణ్ణి చూసి సౌదాసుడు కరిగిపోయి ఆయనను వదిలిపెట్టాడు — మళ్ళీ ఈ దారిన రావద్దని సలహా కూడా ఇచ్చాడు."]
  ],
  [
   ["h", "The Bilva Tree and the Anthill", "మారేడు చెట్టు — పుట్ట"],
   ["p", "On the way home Uttaṅka grew hungry. He tied the earrings up in his deerskin, hung it on a bilva tree, and climbed up to pick the fruit. The bundle came loose and fell to the ground — and at once a serpent seized the earrings and slid away into an anthill. Madayantī's warning had come true.", "ఇంటికి వెళ్ళే దారిలో ఉత్తంకునికి ఆకలి వేసింది. కుండలాలను తన కృష్ణాజినంలో కట్టి, మారేడు చెట్టుకు తగిలించి, పండ్లు కోయడానికి చెట్టెక్కాడు. ఆ మూట వదులై కింద పడింది — వెంటనే ఒక సర్పం కుండలాలను పట్టుకుని పుట్టలోకి జారిపోయింది. మదయంతి హెచ్చరిక నిజమైంది."],
   ["p", "Uttaṅka jumped down and began to dig at the anthill with a stick, in fury and despair. He dug for thirty-five days. Then {indra|Indra} came to him disguised as an old brāhmaṇa. “This is useless,” he said. “The serpent world is thousands of leagues below. You cannot dig there with a stick.” “If I do not get the earrings back,” said Uttaṅka, “I will give up my life right here.” Indra could not change his mind — so he put his thunderbolt into Uttaṅka's stick, and the earth broke open to the serpent world.", "ఉత్తంకుడు కిందికి దూకి, కోపంతో, నిరాశతో, కర్రతో పుట్టను తవ్వడం మొదలుపెట్టాడు. ముప్పై ఐదు రోజులు తవ్వాడు. అప్పుడు {indra|ఇంద్రుడు} ఒక వృద్ధ బ్రాహ్మణుని వేషంలో వచ్చాడు. “ఇది వ్యర్థం. నాగలోకం వేలాది యోజనాల కింద ఉంది. కర్రతో అక్కడికి తవ్వలేవు” అన్నాడు. “కుండలాలు తిరిగి దొరక్కపోతే ఇక్కడే ప్రాణం విడుస్తాను” అన్నాడు ఉత్తంకుడు. ఆయన మనసు మార్చలేక, ఇంద్రుడు తన వజ్రాన్ని ఉత్తంకుని కర్రలో పెట్టాడు; భూమి చీలి నాగలోకానికి దారి తెరుచుకుంది."],
   ["p", "Down below, Uttaṅka saw a blazing horse with a black and white tail and copper-red eyes. It was {agni|Agni} himself — the same fire Uttaṅka had tended for so many years in his teacher's hermitage. The horse told him to blow into its back. Uttaṅka blew, and smoke and flame poured through the serpent world until the frightened nāgas came out with the earrings and gave them up. Uttaṅka hurried home and laid them before {ahalya|Ahalyā}, and she and {gautama|Gautama} blessed him. “That,” says Vaiśampāyana, “was the tapas of Uttaṅka.”", "కింద ఉత్తంకునికి నలుపు తెలుపు తోక, రాగి ఎరుపు కళ్ళు ఉన్న ఒక జ్వలించే గుర్రం కనిపించింది. అది స్వయంగా {agni|అగ్నిదేవుడు} — గురువు ఆశ్రమంలో ఉత్తంకుడు ఎన్నో ఏళ్ళు సేవించిన అదే అగ్ని. తన వెనుక భాగంలోకి ఊదమని గుర్రం చెప్పింది. ఉత్తంకుడు ఊదాడు; పొగ, మంటలు నాగలోకమంతా వ్యాపించాయి; భయపడిన నాగులు కుండలాలతో బయటికి వచ్చి అప్పగించారు. ఉత్తంకుడు త్వరగా ఇంటికి వెళ్ళి వాటిని {ahalya|అహల్య} ముందు ఉంచాడు; ఆమె, {gautama|గౌతముడు} ఆయనను ఆశీర్వదించారు. “ఇదీ ఉత్తంకుని తపస్సు” అంటాడు వైశంపాయనుడు."],
   ["src", "Mahābhārata, Āśvamedhika Parva, the Uttaṅka episode — the meeting with the man-eating Saudāsa, Madayantī and the sign, Uttaṅka's return to keep his promise, the bilva tree, the serpent and the anthill, thirty-five days of digging, Indra's thunderbolt, the horse that was Agni, and the earrings given to Ahalyā. How Saudāsa came under the curse: Mahābhārata, Ādi Parva.", "మహాభారతం, ఆశ్వమేధిక పర్వం, ఉత్తంకోపాఖ్యానం — నరభక్షకుడైన సౌదాసునితో కలయిక, మదయంతి, గుర్తు, మాట నిలుపుకోవడానికి ఉత్తంకుడు తిరిగి వెళ్ళడం, మారేడు చెట్టు, సర్పం, పుట్ట, ముప్పై ఐదు రోజుల తవ్వకం, ఇంద్రుని వజ్రం, అగ్నిరూపమైన గుర్రం, అహల్యకు కుండలాలు. సౌదాసునికి శాపం వచ్చిన కథ: మహాభారతం, ఆది పర్వం."]
  ]
 ],
 remember: [
  ["{uttanka|Uttaṅka} promised the man-eating {kalmashapada|Saudāsa} he would return — and he did.", "నరభక్షకుడైన {kalmashapada|సౌదాసునికి} తిరిగి వస్తానని {uttanka|ఉత్తంకుడు} మాట ఇచ్చాడు — నిలబెట్టుకున్నాడు."],
  ["Queen {madayanti|Madayantī} gave the earrings only after a sign from her husband.", "భర్త దగ్గరి నుండి గుర్తు వచ్చాకే రాణి {madayanti|మదయంతి} కుండలాలు ఇచ్చింది."],
  ["A serpent stole them from under a bilva tree; after 35 days of digging, {indra|Indra}'s vajra and {agni|Agni}'s smoke won them back.", "మారేడు చెట్టు కింద సర్పం వాటిని దొంగిలించింది; 35 రోజుల తవ్వకం తరువాత {indra|ఇంద్రుని} వజ్రం, {agni|అగ్ని} పొగ వాటిని తిరిగి తెచ్చాయి."]
 ],
 think: ["Uttaṅka walked back to a man-eater only because he had given his word. What makes a promise so strong that a person would keep it even at such a cost?", "మాట ఇచ్చాడు కాబట్టే ఉత్తంకుడు నరభక్షకుని దగ్గరకు తిరిగి నడిచాడు. ఇంత మూల్యం చెల్లించైనా నిలుపుకునేంత బలం ఒక వాగ్దానానికి ఎక్కడి నుండి వస్తుంది?"]
},
{
 id: "ut-9", sage: "uttanka", n: 9, order: 2409, date: "2026-10-25",
 title: "Kṛṣṇa in the Desert", titleTe: "ఎడారిలో శ్రీకృష్ణుడు",
 src: "Mahābhārata, Āśvamedhika Parva",
 who: ["uttanka", "krishna", "arjuna"],
 pages: [
  [
   ["p", "The great war at Kurukṣetra was over. {krishna|Kṛṣṇa} had stayed on with the Pāṇḍavas for a while, and then set out for home, for Dvārakā, across the desert. There, in the waste of sand, he came upon the hermitage of {uttanka|Uttaṅka}, now an ascetic of great power. Kṛṣṇa honoured him, and the sage honoured Kṛṣṇa in return.", "కురుక్షేత్ర మహాయుద్ధం ముగిసింది. {krishna|శ్రీకృష్ణుడు} కొంత కాలం పాండవులతో ఉండి, తరువాత ఎడారి మీదుగా తన ద్వారకకు బయలుదేరాడు. ఆ ఇసుక మైదానంలో ఇప్పుడు గొప్ప తపశ్శక్తి గల తపస్వి అయిన {uttanka|ఉత్తంకుని} ఆశ్రమం కనిపించింది. కృష్ణుడు ఆయనను పూజించాడు; ముని కూడా కృష్ణుణ్ణి సత్కరించాడు."],
   ["p", "Uttaṅka had been in the desert a long time, lost in tapas, and had not heard the news. He asked eagerly: “Kṛṣṇa, you went to the house of the Kurus to make peace between those cousins, the Kauravas and the Pāṇḍavas. Have you made a lasting peace between them? Are they living together as brothers now?”", "ఉత్తంకుడు చాలా కాలంగా ఎడారిలో తపస్సులో మునిగి ఉన్నాడు; వార్తలేవీ వినలేదు. ఆత్రంగా అడిగాడు: “కృష్ణా, అన్నదమ్ముల బిడ్డలైన కౌరవులకు, పాండవులకు సంధి చేయడానికి నువ్వు కురువంశీయుల ఇంటికి వెళ్ళావు కదా. వారి మధ్య శాశ్వత సంధి కుదిర్చావా? వారిప్పుడు అన్నదమ్ముల్లా కలిసి ఉంటున్నారా?”"],
   ["p", "Kṛṣṇa told him the truth. “I tried hard to bring peace, but the Kauravas would not have it. All of them went to their death in the war, with their friends and their armies. No one can overrule fate, by wisdom or by strength. Only the five Pāṇḍavas are left, their friends and their sons all killed.”", "కృష్ణుడు నిజమే చెప్పాడు: “సంధి కోసం ఎంతో ప్రయత్నించాను, కానీ కౌరవులు ఒప్పుకోలేదు. వారంతా తమ మిత్రులతో, సైన్యాలతో యుద్ధంలో మరణించారు. బుద్ధితో గానీ బలంతో గానీ విధిని ఎవరూ దాటలేరు. పాండవులు ఐదుగురే మిగిలారు; వారి మిత్రులు, పుత్రులు అందరూ చనిపోయారు.”"]
  ],
  [
   ["h", "“I Will Curse You”", "“నిన్ను శపిస్తాను”"],
   ["p", "Uttaṅka's eyes blazed with anger. “Kṛṣṇa! You were able to save them, and you did not. Those Kurus were your own kin, and you let them perish. Therefore I will curse you. You could have stopped it by force, and you looked away.”", "ఉత్తంకుని కళ్ళు కోపంతో మండాయి. “కృష్ణా! వారిని కాపాడగలిగి కూడా కాపాడలేదు. ఆ కురువంశీయులు నీ బంధువులే — అయినా వారిని నశించనిచ్చావు. అందుకే నిన్ను శపిస్తాను. బలవంతంగానైనా ఆపగలిగి ఉండీ పట్టించుకోలేదు.”"],
   ["p", "Kṛṣṇa did not grow angry. “Listen to me first, Uttaṅka,” he said. “Then curse me if you still wish. You have gathered great tapas, and pleased your teachers. I do not want you to lose that tapas. No one can destroy me with a curse, however great his penance. Hear what I have to say.”", "కృష్ణునికి కోపం రాలేదు. “ఉత్తంకా, ముందు నా మాట విను,” అన్నాడు. “ఆ తరువాత కూడా కావాలనుకుంటే శపించు. నువ్వు గొప్ప తపస్సు సంపాదించావు; గురువులను సంతోషపెట్టావు. ఆ తపస్సు నువ్వు పోగొట్టుకోవడం నాకు ఇష్టం లేదు. ఎంత తపస్సు ఉన్నా, శాపంతో నన్నెవరూ నాశనం చేయలేరు. నేను చెప్పేది విను.”"],
   ["p", "Then Kṛṣṇa taught him about the Self — that he himself is the existent and the non-existent, the source and the end of all things, and that to protect dharma he takes birth again and again in many wombs. “When I am born among the gods, I act as a god. Among the gandharvas I act as a gandharva, among the serpents as a serpent. Now I have been born as a man, and I acted as a man must. I begged the Kauravas, I pleaded with them, I even frightened them — but, driven by their own wrongs, they would not listen. So they died in battle, according to dharma.”", "తరువాత కృష్ణుడు ఆత్మ గురించి బోధించాడు — సత్తు, అసత్తు రెండూ తానేనని, సమస్తానికీ మూలమూ, అంతమూ తానేనని, ధర్మరక్షణ కోసం ఎన్నో యోనుల్లో మళ్ళీ మళ్ళీ పుడతానని. “దేవతల మధ్య పుట్టినప్పుడు దేవునిలా నడుచుకుంటాను. గంధర్వుల మధ్య గంధర్వునిలా, నాగుల మధ్య నాగునిలా. ఇప్పుడు మనిషిగా పుట్టాను; మనిషి నడుచుకోవలసినట్లే నడుచుకున్నాను. కౌరవులను బతిమాలాను, వేడుకున్నాను, భయపెట్టాను కూడా — కానీ తమ తప్పులకు లోనై వారు వినలేదు. అందుకే ధర్మం ప్రకారం యుద్ధంలో మరణించారు.”"]
  ],
  [
   ["h", "The Universal Form", "విశ్వరూపం"],
   ["p", "Uttaṅka's anger left him. “I know you now, Lord of the world,” he said. “Show me your own form, if you are pleased with me.” And Kṛṣṇa, pleased, showed him the very same eternal, all-containing form that {arjuna|Arjuna} had seen on the battlefield before the war — blazing like a thousand suns, filling the sky, holding the whole universe within it.", "ఉత్తంకుని కోపం పోయింది. “జగత్ప్రభూ, ఇప్పుడు నిన్ను తెలుసుకున్నాను. నాపై ప్రసన్నుడవైతే నీ నిజరూపం చూపించు” అని వేడుకున్నాడు. సంతోషించిన కృష్ణుడు యుద్ధానికి ముందు రణభూమిలో {arjuna|అర్జునుడు} చూసిన అదే శాశ్వతమైన, సమస్తాన్నీ తనలో ఉంచుకున్న విశ్వరూపాన్ని చూపించాడు — వేయి సూర్యుల్లా జ్వలిస్తూ, ఆకాశాన్ని నింపుతూ, విశ్వమంతటినీ తనలో ధరిస్తూ."],
   ["p", "Uttaṅka bowed and praised him. Kṛṣṇa withdrew the form and said, “Choose a boon.” “Seeing this form of yours is boon enough,” said Uttaṅka. But Kṛṣṇa insisted, and the sage, who lived in a land without water, made a simple request: “Then let me find water wherever I wish for it in this desert.” “Think of me when you need it,” said Kṛṣṇa, and went on his way to Dvārakā.", "ఉత్తంకుడు నమస్కరించి స్తుతించాడు. కృష్ణుడు ఆ రూపాన్ని ఉపసంహరించి, “వరం కోరుకో” అన్నాడు. “నీ ఈ రూపాన్ని చూడడమే నాకు చాలు” అన్నాడు ఉత్తంకుడు. కానీ కృష్ణుడు పట్టుబట్టాడు. నీళ్ళు లేని నేలలో నివసించే ఆ ముని ఒక చిన్న కోరిక కోరాడు: “అయితే ఈ ఎడారిలో ఎక్కడ కోరుకుంటే అక్కడ నాకు నీళ్ళు దొరకాలి.” “అవసరమైనప్పుడు నన్ను తలచుకో” అని చెప్పి కృష్ణుడు ద్వారకకు సాగిపోయాడు."],
   ["dyk", "🌌", "Arjuna is not the only one to see the universal form. The Mahābhārata also tells of Kṛṣṇa showing a divine form in the Kaurava court — and here, to an angry old sage in the desert.", "విశ్వరూపం చూసినది అర్జునుడు ఒక్కడే కాదు. కౌరవ సభలో కృష్ణుడు దివ్యరూపం చూపిన సంగతి కూడా మహాభారతం చెబుతుంది — ఇక్కడ ఎడారిలో కోపంగా ఉన్న ఒక వృద్ధ మునికి కూడా."],
   ["src", "Mahābhārata, Āśvamedhika Parva, the Uttaṅka episode — Kṛṣṇa's meeting with Uttaṅka on his way to Dvārakā, the threat of a curse, Kṛṣṇa's teaching about himself and his births, the vision of the universal form, and the boon of water in the desert.", "మహాభారతం, ఆశ్వమేధిక పర్వం, ఉత్తంకోపాఖ్యానం — ద్వారకకు వెళ్తూ కృష్ణుడు ఉత్తంకుని కలవడం, శాపం బెదిరింపు, తన గురించి, తన జన్మల గురించి కృష్ణుని బోధ, విశ్వరూప దర్శనం, ఎడారిలో నీటి వరం."]
  ]
 ],
 remember: [
  ["When {krishna|Kṛṣṇa} told him the Kauravas were all dead, {uttanka|Uttaṅka} threatened to curse him.", "కౌరవులంతా చనిపోయారని {krishna|కృష్ణుడు} చెప్పగానే {uttanka|ఉత్తంకుడు} శపిస్తానని బెదిరించాడు."],
  ["Kṛṣṇa explained that he acts as a god among gods and as a man among men, and had tried for peace.", "దేవతల మధ్య దేవునిలా, మనుషుల మధ్య మనిషిలా నడుచుకుంటానని, సంధికి ప్రయత్నించానని కృష్ణుడు వివరించాడు."],
  ["He showed Uttaṅka the universal form {arjuna|Arjuna} had seen, and gave him a boon of water.", "{arjuna|అర్జునుడు} చూసిన విశ్వరూపాన్ని ఉత్తంకునికి చూపి, నీటి వరం ఇచ్చాడు."]
 ],
 think: ["Uttaṅka was ready to curse before he had heard the whole story. Kṛṣṇa answered not with anger but with an explanation. What does it take to listen first when you are sure you are right?", "పూర్తి కథ వినకముందే ఉత్తంకుడు శపించడానికి సిద్ధపడ్డాడు. కృష్ణుడు కోపంతో కాక వివరణతో జవాబిచ్చాడు. మనదే న్యాయం అని గట్టిగా అనిపిస్తున్నప్పుడు ముందు వినడానికి ఏం కావాలి?"]
},
{
 id: "ut-10", sage: "uttanka", n: 10, order: 2410, date: "2026-10-25",
 title: "The Hunter's Water — and the Uttaṅka Clouds", titleTe: "వేటగాని నీళ్ళు — ఉత్తంక మేఘాలు",
 src: "Mahābhārata, Āśvamedhika Parva",
 who: ["uttanka", "krishna", "indra"],
 pages: [
  [
   ["p", "One day, wandering in the desert, {uttanka|Uttaṅka} grew terribly thirsty. He searched everywhere for water and found none. Then he remembered his boon and thought of {krishna|Kṛṣṇa}.", "ఒక రోజు ఎడారిలో తిరుగుతుండగా {uttanka|ఉత్తంకునికి} భరించలేని దాహం వేసింది. అంతటా నీటి కోసం వెతికాడు; ఎక్కడా దొరకలేదు. అప్పుడు తన వరం గుర్తొచ్చి {krishna|కృష్ణుణ్ణి} తలచుకున్నాడు."],
   ["p", "At once he saw a man coming towards him across the sand: a hunter of the lowest caste, naked, filthy, with a sword and a bow, surrounded by a pack of dogs. And from the man's body, from a vessel he carried, flowed a stream of water. The hunter smiled at him. “Uttaṅka, take this water from me,” he said. “I felt pity when I saw you so thirsty.”", "వెంటనే ఇసుకలో తన వైపు వస్తున్న ఒక మనిషి కనిపించాడు — అతి నీచ కులానికి చెందిన ఒక వేటగాడు; దిగంబరంగా, మురికిగా, కత్తి, విల్లు పట్టుకుని, చుట్టూ కుక్కల గుంపుతో. అతని దేహం నుండి, అతను మోస్తున్న పాత్ర నుండి నీటి ధార ప్రవహిస్తోంది. ఆ వేటగాడు నవ్వుతూ, “ఉత్తంకా, నా దగ్గరి నుండి ఈ నీళ్ళు తీసుకో. ఇంత దాహంగా ఉన్న నిన్ను చూసి జాలేసింది” అన్నాడు."],
   ["p", "Uttaṅka recoiled. Proud of his purity, disgusted by the man and his dogs, he would not take water from such a hand. He refused, and even spoke harshly to him. The hunter kept urging him, again and again, “Drink!” — and when Uttaṅka would not, the man and his dogs simply vanished.", "ఉత్తంకుడు వెనక్కి తగ్గాడు. తన శుచిపై గర్వంతో, ఆ మనిషిని, అతని కుక్కలను చూసి అసహ్యపడి, అలాంటి చేతి నుండి నీళ్ళు తీసుకోవడానికి ఒప్పుకోలేదు. తిరస్కరించడమే కాక కటువుగా కూడా మాట్లాడాడు. “తాగు!” అని ఆ వేటగాడు మళ్ళీ మళ్ళీ బతిమాలాడు — ఉత్తంకుడు ఒప్పుకోకపోవడంతో అతడూ, అతని కుక్కలూ అదృశ్యమైపోయారు."]
  ],
  [
   ["h", "It Was Indra", "అతడు ఇంద్రుడే"],
   ["p", "Uttaṅka was shaken. He understood that he had been tested and had failed. Then Kṛṣṇa appeared, holding his conch and discus. Uttaṅka said, “Lord, was that right — to send me water in the form of an outcaste?”", "ఉత్తంకుడు కలవరపడ్డాడు. తనను పరీక్షించారని, తాను ఓడిపోయానని అర్థమైంది. అప్పుడు శంఖ చక్రాలు ధరించి కృష్ణుడు ప్రత్యక్షమయ్యాడు. “స్వామీ, అంటరానివాని రూపంలో నాకు నీళ్ళు పంపడం సరైనదేనా?” అని ఉత్తంకుడు అడిగాడు."],
   ["p", "Kṛṣṇa answered: “Uttaṅka, for your sake I asked {indra|Indra} to give you amṛta, the drink of the immortals, in place of water. Indra said, ‘A mortal should not become immortal; let him have some other gift.’ But I pressed him, and at last he agreed — on one condition. ‘I will go to him in the form of an outcaste hunter and offer him the amṛta. If he takes it, he shall have it. If he turns it away, he shall not.’ And you turned it away.”", "కృష్ణుడు చెప్పాడు: “ఉత్తంకా, నీ కోసం నీళ్ళ బదులు దేవతల పానీయమైన అమృతం ఇవ్వమని {indra|ఇంద్రుణ్ణి} అడిగాను. ‘మానవుడు అమరుడు కాకూడదు; అతనికి వేరే ఏదైనా వరం ఇవ్వండి’ అన్నాడు ఇంద్రుడు. నేను పట్టుబట్టాను. చివరికి ఒక షరతుతో ఒప్పుకున్నాడు — ‘అంటరాని వేటగాని రూపంలో వెళ్ళి అతనికి అమృతం ఇస్తాను. తీసుకుంటే అతనిదే. తిరస్కరిస్తే దక్కదు.’ నువ్వు తిరస్కరించావు.”"],
   ["p", "The sage who had been ready to curse Kṛṣṇa for failing others had now failed himself — not in courage, not in tapas, but in seeing past the outside of a person. Uttaṅka bowed his head.", "ఇతరులను కాపాడలేదని కృష్ణుణ్ణి శపించడానికి సిద్ధపడిన ముని, ఇప్పుడు తానే ఓడిపోయాడు — ధైర్యంలో కాదు, తపస్సులో కాదు, ఒక మనిషి బయటి రూపాన్ని దాటి చూడడంలో. ఉత్తంకుడు తల వంచుకున్నాడు."]
  ],
  [
   ["h", "The Clouds That Carry His Name", "ఆయన పేరు మోసే మేఘాలు"],
   ["p", "But Kṛṣṇa did not leave him thirsty. “I will give you another boon,” he said. “Whenever you wish for water, clouds full of water will gather over this desert and rain sweet water for you. They will be called the Uttaṅka clouds.” And so it was. And the Mahābhārata says that the rain clouds which pour down on the desert are called the Uttaṅka-meghas — the clouds of Uttaṅka.", "అయినా కృష్ణుడు ఆయనను దాహంతో వదిలేయలేదు. “నీకు ఇంకొక వరం ఇస్తాను,” అన్నాడు. “నువ్వు నీళ్ళు కోరినప్పుడల్లా నీటితో నిండిన మేఘాలు ఈ ఎడారి మీద కమ్ముకుని నీ కోసం తియ్యని నీటిని కురిపిస్తాయి. వాటిని ఉత్తంక మేఘాలు అని పిలుస్తారు.” అలాగే జరిగింది. ఎడారి మీద కురిసే ఆ వర్షమేఘాలను ‘ఉత్తంక మేఘాలు’ అంటారని మహాభారతం చెబుతుంది."],
   ["dyk", "🌧️", "Uttaṅka refused amṛta because of how the giver looked. In the Ādi Parva story, he had eaten a bull's dung on a stranger's word — and that, too, turned out to be amṛta. One telling rewards his trust; the other shows the price of his pride.", "ఇచ్చేవాని రూపం చూసి ఉత్తంకుడు అమృతాన్ని తిరస్కరించాడు. ఆది పర్వ కథలోనేమో ఒక అపరిచితుని మాట మీద ఎద్దు పేడ తిన్నాడు — అది కూడా అమృతమే అని తేలింది. ఒక కథనం ఆయన నమ్మకానికి ఫలం ఇస్తుంది; మరొకటి ఆయన గర్వానికి మూల్యం చూపిస్తుంది."],
   ["src", "Mahābhārata, Āśvamedhika Parva, the Uttaṅka episode — Indra in the form of an outcaste hunter with dogs offering amṛta, Uttaṅka's refusal, Kṛṣṇa's explanation, and the boon of the Uttaṅka clouds (uttaṅka-megha) that rain in the desert.", "మహాభారతం, ఆశ్వమేధిక పర్వం, ఉత్తంకోపాఖ్యానం — కుక్కలతో వచ్చిన అంటరాని వేటగాని రూపంలో ఇంద్రుడు అమృతం ఇవ్వబోవడం, ఉత్తంకుని తిరస్కారం, కృష్ణుని వివరణ, ఎడారిలో కురిసే ‘ఉత్తంక మేఘాల’ వరం."]
  ]
 ],
 remember: [
  ["{indra|Indra} came as an outcaste hunter with dogs, offering {uttanka|Uttaṅka} amṛta as water.", "{indra|ఇంద్రుడు} కుక్కలతో ఉన్న అంటరాని వేటగాని రూపంలో వచ్చి {uttanka|ఉత్తంకునికి} నీళ్ళుగా అమృతం ఇవ్వబోయాడు."],
  ["Uttaṅka refused it out of disgust, and so lost the gift of immortality.", "అసహ్యంతో ఉత్తంకుడు దాన్ని తిరస్కరించి అమరత్వ వరాన్ని పోగొట్టుకున్నాడు."],
  ["{krishna|Kṛṣṇa} gave him the Uttaṅka clouds, which rain on the desert whenever he wishes.", "ఆయన కోరినప్పుడల్లా ఎడారిలో కురిసే ఉత్తంక మేఘాలను {krishna|కృష్ణుడు} వరంగా ఇచ్చాడు."]
 ],
 think: ["Uttaṅka could face a man-eater and dig for thirty-five days, yet he could not accept water from a poor hunter. Why can it be harder to set aside our pride than to be brave?", "నరభక్షకుణ్ణి ఎదుర్కొని, ముప్పై ఐదు రోజులు తవ్వగలిగిన ఉత్తంకుడు, ఒక పేద వేటగాని చేతి నీళ్ళు మాత్రం తీసుకోలేకపోయాడు. ధైర్యంగా ఉండడం కంటే గర్వాన్ని వదులుకోవడం ఎందుకు కష్టం?"]
},
{
 id: "ut-11", sage: "uttanka", n: 11, order: 2411, date: "2026-10-25",
 title: "Dhundhu Under the Sand", titleTe: "ఇసుక కింద ధుంధుడు",
 src: "Mahābhārata, Vana Parva · Rāmāyaṇa · Purāṇas",
 who: ["uttanka", "vishnu", "brihadashva", "kuvalashva", "dhundhu", "brahma", "markandeya", "yudhishthira"],
 pages: [
  [
   ["p", "The third telling comes from the Vana Parva, where the ancient sage {markandeya|Mārkaṇḍeya} tells {yudhishthira|Yudhiṣṭhira} the story of a king called Dhundhumāra, “Slayer of Dhundhu”. Here {uttanka|Uttaṅka} is an old ascetic living in a hermitage in the desert. For many years he did fierce tapas, until {vishnu|Viṣṇu} himself appeared before him.", "మూడవ కథనం అరణ్య పర్వం నుండి — అక్కడ ప్రాచీన మహాముని {markandeya|మార్కండేయుడు} {yudhishthira|ధర్మరాజుకు} ‘ధుంధుని చంపినవాడు’ అనే అర్థం గల ధుంధుమారుడనే రాజు కథ చెబుతాడు. ఇక్కడ {uttanka|ఉత్తంకుడు} ఎడారిలోని ఆశ్రమంలో నివసించే వృద్ధ తపస్వి. ఎన్నో ఏళ్ళు ఉగ్ర తపస్సు చేశాడు; చివరికి స్వయంగా {vishnu|విష్ణువే} ఆయన ఎదుట ప్రత్యక్షమయ్యాడు."],
   ["p", "Uttaṅka praised him with deep devotion, and Viṣṇu offered him a boon. “To have seen you is the greatest boon of all,” said the sage. But when pressed, he asked: “Let my mind always rest in dharma, in truth and in self-control, and let me always be devoted to you.” Viṣṇu granted it, and added: “Through you a great good will come to the worlds. A king named Kuvalāśva will kill the mighty demon Dhundhu — and at your request I will enter him with my power.”", "ఉత్తంకుడు గాఢమైన భక్తితో స్తుతించాడు; విష్ణువు వరం కోరుకోమన్నాడు. “నిన్ను దర్శించడమే అన్నిటికంటే గొప్ప వరం” అన్నాడు ముని. పట్టుబడితే ఇలా కోరాడు: “నా మనసు ఎప్పుడూ ధర్మంలో, సత్యంలో, ఇంద్రియ నిగ్రహంలో నిలిచి ఉండాలి; ఎప్పుడూ నీపై భక్తి ఉండాలి.” విష్ణువు అనుగ్రహించి ఇంకా ఇలా అన్నాడు: “నీ ద్వారా లోకాలకు గొప్ప మేలు జరుగుతుంది. కువలాశ్వుడనే రాజు మహాబలుడైన ధుంధు రాక్షసుణ్ణి చంపుతాడు — నీ కోరిక మేరకు నా శక్తితో నేను అతనిలో ప్రవేశిస్తాను.”"]
  ],
  [
   ["h", "The Demon Who Breathed Fire Under the Earth", "భూమి కింద నిప్పు ఊపిరి"],
   ["p", "Near Uttaṅka's hermitage, in a sea of sand, lay a demon named {dhundhu|Dhundhu}, son of Madhu and Kaiṭabha, the two demons Viṣṇu had once slain. Dhundhu had done great tapas and won a boon from {brahma|Brahmā} that no god, demon, yakṣa, serpent, gandharva or rākṣasa could kill him. Then he buried himself deep under the sand, still doing tapas — for the ruin of the worlds.", "ఉత్తంకుని ఆశ్రమానికి దగ్గరలో, ఇసుక సముద్రంలో {dhundhu|ధుంధుడు} అనే రాక్షసుడు పడుకుని ఉన్నాడు. ఒకప్పుడు విష్ణువు సంహరించిన మధుకైటభుల కుమారుడు అతడు. గొప్ప తపస్సు చేసి {brahma|బ్రహ్మదేవుని} నుండి — దేవతలు, దానవులు, యక్షులు, నాగులు, గంధర్వులు, రాక్షసులు ఎవరూ తనను చంపలేరనే వరం పొందాడు. ఆ తరువాత లోకాల నాశనం కోసమే తపస్సు చేస్తూ ఇసుక లోతుల్లో దాక్కున్నాడు."],
   ["p", "Once a year, at the year's end, Dhundhu breathed out — and the whole earth shook for seven days with its mountains and forests. A storm of dust rose and hid the sun. Sparks, flames and smoke poured from the ground. No one could live near that place, and Uttaṅka could not stay in peace in his own hermitage.", "సంవత్సరానికి ఒకసారి, ఏడాది చివర్లో ధుంధుడు ఊపిరి వదిలేవాడు — ఏడు రోజుల పాటు కొండలు, అడవులతో సహా భూమి అంతా కంపించేది. దుమ్ము తుఫాను లేచి సూర్యుణ్ణి కప్పేసేది. నేల నుండి నిప్పురవ్వలు, మంటలు, పొగ పైకి లేచేవి. ఆ ప్రాంతంలో ఎవరూ ఉండలేకపోయేవారు; ఉత్తంకుడు కూడా తన ఆశ్రమంలో ప్రశాంతంగా ఉండలేకపోయాడు."],
   ["p", "At that time the Ikṣvāku king {brihadashva|Bṛhadaśva} had crowned his son {kuvalashva|Kuvalāśva} and was leaving for the forest. Uttaṅka stopped him on the way. “Protecting your people is your first duty,” he said. “You cannot go to the forest yet. Near my hermitage lies Dhundhu, troubling the whole world. Kill him, and Viṣṇu will add his power to yours.” Bṛhadaśva answered, “I have laid down my weapons. But my son Kuvalāśva will do this, with his sons.”", "ఆ సమయంలో ఇక్ష్వాకు రాజు {brihadashva|బృహదశ్వుడు} తన కుమారుడు {kuvalashva|కువలాశ్వునికి} పట్టాభిషేకం చేసి అడవికి బయలుదేరుతున్నాడు. ఉత్తంకుడు దారిలో ఆయనను ఆపాడు. “ప్రజలను కాపాడడమే మీ మొదటి ధర్మం. ఇప్పుడే అడవికి వెళ్ళకూడదు. నా ఆశ్రమం దగ్గర ధుంధుడు పడుకుని లోకమంతటినీ బాధిస్తున్నాడు. అతణ్ణి చంపండి; విష్ణువు తన శక్తిని మీ శక్తికి జోడిస్తాడు” అన్నాడు. బృహదశ్వుడు బదులిచ్చాడు: “నేను ఆయుధాలు విడిచిపెట్టాను. కానీ నా కుమారుడు కువలాశ్వుడు తన కుమారులతో కలిసి ఈ పని చేస్తాడు.”"]
  ],
  [
   ["h", "Dhundhumāra", "ధుంధుమారుడు"],
   ["p", "Kuvalāśva set out with his twenty-one thousand sons and his army, with Uttaṅka leading the way, and Viṣṇu entered him with his power. For seven days the princes dug through the sand. At last the vast demon rose from the depths, and from his mouth poured a fire like the fire at the end of the world. It burned all of Kuvalāśva's sons except three.", "కువలాశ్వుడు తన ఇరవై ఒక్క వేల మంది కుమారులతో, సైన్యంతో బయలుదేరాడు; ఉత్తంకుడు దారి చూపించాడు; విష్ణువు తన శక్తితో కువలాశ్వునిలో ప్రవేశించాడు. ఏడు రోజుల పాటు రాజకుమారులు ఇసుకను తవ్వారు. చివరికి ఆ మహాకాయుడైన రాక్షసుడు లోతుల నుండి పైకి లేచాడు; అతని నోటి నుండి ప్రళయాగ్ని లాంటి మంటలు వెల్లువెత్తాయి. ముగ్గురు తప్ప కువలాశ్వుని కుమారులందరూ ఆ మంటల్లో కాలిపోయారు."],
   ["p", "Then Kuvalāśva, a great yogī as well as a warrior, released a flood of water from his own body and put out the demon's fire. With a mighty weapon he struck Dhundhu down and killed him. The gods and sages praised him, and from that day he was called {kuvalashva|Dhundhumāra}, the Slayer of Dhundhu. Uttaṅka blessed him, and the desert was at peace. The three sons who survived carried on the royal line.", "అప్పుడు యోధుడే కాక మహాయోగి కూడా అయిన కువలాశ్వుడు తన దేహం నుండే జలప్రవాహాన్ని వదిలి రాక్షసుని మంటలను ఆర్పేశాడు. ఒక మహాస్త్రంతో ధుంధుణ్ణి కొట్టి సంహరించాడు. దేవతలు, మునులు ఆయనను పొగిడారు; ఆ రోజు నుండి ఆయనను {kuvalashva|ధుంధుమారుడు} — ధుంధుని చంపినవాడు — అని పిలిచారు. ఉత్తంకుడు ఆశీర్వదించాడు; ఎడారి శాంతించింది. మిగిలిన ముగ్గురు కుమారులు రాజవంశాన్ని కొనసాగించారు."],
   ["dyk", "👑", "Dhundhumāra was an ancestor of Rāma: his name appears in the Rāmāyaṇa's lists of the Ikṣvāku kings. The Purāṇas, too, tell of Kuvalāśva and the demon under the sand, more briefly than the Mahābhārata.", "ధుంధుమారుడు శ్రీరాముని పూర్వీకుడు — రామాయణంలోని ఇక్ష్వాకు రాజుల వంశావళిలో ఆయన పేరు ఉంది. పురాణాలు కూడా కువలాశ్వుని, ఇసుక కింది రాక్షసుని కథను మహాభారతం కంటే క్లుప్తంగా చెబుతాయి."]
  ],
  [
   ["h", "Uttaṅka, the Pupil Who Would Not Give Up", "పట్టు వదలని శిష్యుడు — ఉత్తంకుడు"],
   ["p", "So we have three Uttaṅkas, or one Uttaṅka told three ways: the pupil who would not cross a line and would not give up on a task; the angry seer who lit the snake sacrifice and dared to rebuke Kṛṣṇa; and the old ascetic of the desert whose prayer brought down a demon. Through all of them runs the same fierce, stubborn heart.", "అలా మనకు ముగ్గురు ఉత్తంకులు — లేదా మూడు విధాలుగా చెప్పబడిన ఒకే ఉత్తంకుడు: గీత దాటని, చేపట్టిన పనిని వదలని శిష్యుడు; సర్పయాగాన్ని రగిలించి కృష్ణుణ్ణే నిలదీసిన కోపిష్ఠి ముని; తన ప్రార్థనతో ఒక రాక్షసుణ్ణి నేలకూల్చిన ఎడారి వృద్ధ తపస్వి. వీరందరిలోనూ అదే తీవ్రమైన, పట్టుదల గల హృదయం కనిపిస్తుంది."],
   ["p", "The Mahābhārata does not make him perfect. He curses too quickly, holds grudges, and once turns away amṛta because the hand that offered it was dirty. But he keeps his word to a man-eater, digs for thirty-five days, and is honoured by Indra, by Agni and by Kṛṣṇa. In him the epic shows us what devotion to a teacher can achieve — and what pride can still cost a great soul.", "మహాభారతం ఆయనను పరిపూర్ణునిగా చిత్రించదు. తొందరగా శపిస్తాడు, పగ పెట్టుకుంటాడు, ఇచ్చిన చేయి మురికిగా ఉందని ఒకసారి అమృతాన్నే తిరస్కరిస్తాడు. కానీ నరభక్షకునికి ఇచ్చిన మాట నిలబెట్టుకుంటాడు, ముప్పై ఐదు రోజులు తవ్వుతాడు; ఇంద్రుడు, అగ్ని, కృష్ణుడు ఆయనను గౌరవిస్తారు. గురుభక్తి ఏం సాధించగలదో — గర్వం గొప్పవారికి కూడా ఎంత మూల్యం చెల్లింపజేస్తుందో — ఉత్తంకుని ద్వారా ఇతిహాసం చూపిస్తుంది."],
   ["src", "Mahābhārata, Vana Parva, the Dhundhumāra episode told by Mārkaṇḍeya to Yudhiṣṭhira — Uttaṅka's tapas in the desert and Viṣṇu's boon, Dhundhu son of Madhu and Kaiṭabha, Bṛhadaśva and Kuvalāśva, the killing of Dhundhu and the three surviving sons. Dhundhumāra among the Ikṣvāku kings: Vālmīki Rāmāyaṇa, Bāla Kāṇḍa genealogy. Kuvalāśva and Dhundhu also in the Purāṇas and the Harivaṃśa.", "మహాభారతం, అరణ్య పర్వం, మార్కండేయుడు ధర్మరాజుకు చెప్పిన ధుంధుమారోపాఖ్యానం — ఎడారిలో ఉత్తంకుని తపస్సు, విష్ణువు వరం, మధుకైటభుల కుమారుడు ధుంధుడు, బృహదశ్వుడు, కువలాశ్వుడు, ధుంధు సంహారం, మిగిలిన ముగ్గురు కుమారులు. ఇక్ష్వాకు రాజులలో ధుంధుమారుడు: వాల్మీకి రామాయణం, బాలకాండ వంశావళి. కువలాశ్వుడు, ధుంధుడు పురాణాలలో, హరివంశంలో కూడా."]
  ]
 ],
 remember: [
  ["{vishnu|Viṣṇu} promised {uttanka|Uttaṅka} that King {kuvalashva|Kuvalāśva}, filled with his power, would kill {dhundhu|Dhundhu}.", "తన శక్తి నిండిన {kuvalashva|కువలాశ్వుడు} {dhundhu|ధుంధుణ్ణి} చంపుతాడని {vishnu|విష్ణువు} {uttanka|ఉత్తంకునికి} మాట ఇచ్చాడు."],
  ["Dhundhu lay under the desert sand and shook the earth with his yearly breath.", "ధుంధుడు ఎడారి ఇసుక కింద పడుకుని ఏటా తన ఊపిరితో భూమిని కంపింపజేసేవాడు."],
  ["Kuvalāśva quenched the demon's fire with water from his own body, killed him, and became Dhundhumāra.", "కువలాశ్వుడు తన దేహం నుండి వచ్చిన నీటితో రాక్షసుని మంటలు ఆర్పి, అతణ్ణి చంపి ధుంధుమారుడయ్యాడు."]
 ],
 think: ["Uttaṅka is brave, devoted and stubborn — and also quick to anger and proud. Which of his qualities would you most want, and which would you most want to be free of?", "ఉత్తంకుడు ధైర్యవంతుడు, భక్తుడు, పట్టుదల గలవాడు — తొందరగా కోపపడేవాడు, గర్వం గలవాడు కూడా. ఆయన గుణాలలో మీకు ఏది ఎక్కువగా కావాలి, దేని నుండి ఎక్కువగా విముక్తి కావాలి?"]
}
]);
